INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('f6035de3-64f9-4529-a75a-a2c3b1cc07fe', 'Artistic Swimming Questions Answered', 'artistic-swimming-questions-answered', 'Smiles, Noseclips, and Hair Gel: Your Biggest Artistic Swimming Questions Answered', '<h3>If you''ve ever watched artistic swimming — whether at the Olympics or at a local meet — you probably walked away with a lot of questions. How are they smiling like that? Are their eyes actually open underwater? What is in their hair?!</h3><p>You''re not alone. Artistic swimming is one of the most misunderstood sports out there, and that''s a shame, because the athleticism and artistry involved are genuinely jaw-dropping. Let''s pull back the curtain and answer the questions we hear most often.</p><hr><h3>Why Are They Always Smiling?</h3><p>Here''s the secret: those smiles are part of the performance. Artistic swimmers are trained to make everything look effortless and joyful — even when they''re working incredibly hard beneath the surface.</p><p>That said, the smile isn''t always there. If a routine is set to dramatic or ominous music, you''ll see expressions to match. The smile comes out when the music calls for energy and fun. It''s a performance skill, just like the swimming itself.</p><hr><h3>Do They Touch the Bottom of the Pool?</h3><p>Not a chance — and not just because it''s difficult. Touching the bottom is actually against the rules. Competitors face a two-point deduction if it happens.</p><p>Competition pools must be at least nine feet deep, and swimmers use advanced techniques called <strong>eggbeater kicks</strong> and <strong>sculling</strong> (small, precise arm movements) to suspend themselves in the water. When it looks like a swimmer is "standing" on the surface or launching into the air, that''s pure muscle and technique — no bottom, no floor, no tricks.</p><hr><h3>What''s the Deal With the Poses on Deck?</h3><p>Before entering the water, you''ll often see swimmers strike poses or move on the pool deck while the music plays. This is called <strong>deckwork</strong>, and it sets the mood for the entire routine.</p><p>Deckwork can last no longer than 10 seconds and doesn''t count toward the final score — but it matters. It''s the first impression judges and audiences get, and it gives the team a chance to tell a story from the very first note.</p><hr><h3>What Is That Stuff in Their Hair?</h3><p>Unflavored gelatin — yes, the same Knox gelatin you''d find in a grocery store. It''s mixed into a warm paste, applied to the hair, and left to air-dry until it hardens.</p><p>The gelatin holds up surprisingly well in cold competition pool water and keeps every strand in place throughout the routine. Afterward, it washes out with very hot water. It''s old-school, a little unexpected, and it works perfectly.</p><hr><h3>Are Their Eyes Open Underwater?</h3><p>Yes — always. Goggles aren''t allowed during competition (though swimmers wear them in practice). Keeping their eyes open is essential, because it lets teammates see each other''s positions and make split-second adjustments to stay in sync.</p><p>When a swimmer is spinning upside down, open eyes allow her to spot the pool walls and count rotations — just like a figure skater or diver would. Without that visual anchor, the whole routine falls apart.</p><hr><h3>How Do They Keep Water Out of Their Noses?</h3><p>The noseclip is arguably the most important piece of gear in artistic swimming. It keeps water out during all those upside-down movements and allows swimmers to stay submerged longer. It''s so critical that swimmers tuck a spare noseclip inside their suit during competition — just in case the first one gets knocked off mid-routine.</p><hr><h3>How Long Can They Stay Underwater?</h3><p>Longer than you''d think. In a five-minute routine, a swimmer might spend up to a full minute underwater at a single stretch, and as much as three and a half minutes total — all while actively working her arms and legs to stay in position.</p><p>Elite-level artistic swimmers can travel more than 75 meters underwater without surfacing. That kind of lung capacity and endurance takes years of dedicated training to build.</p><hr><h3>How Much Do They Train?</h3><p>It depends on the level. Beginners and recreational swimmers have a much lighter schedule, while the U.S. Olympic Team trains eight hours a day, six days a week. That time is split across in-water practice, dance, weight training, running, and aerobic conditioning.</p><p>Even at the youth and junior levels, artistic swimming builds incredible physical fitness, body awareness, musicality, and teamwork — skills that carry far beyond the pool.</p><hr><h3>Discover Artistic Swimming in Seattle</h3><p>Whether your child is a beginner swimmer curious about something new, or a competitive athlete looking for a challenge, artistic swimming has something to offer. At <strong>Seattle Synchro</strong>, we welcome kids of all experience levels and help them grow into confident, capable athletes — one eggbeater kick at a time.</p><p>Curious about our programs, summer camp options, or how to get started with kids swimming lessons in Seattle? We''d love to hear from you. <a class="underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current" href="#">Reach out to our team or explore our classes</a> — and come see what artistic swimming in Seattle is all about.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1778009763855-4znfaq7ipyn.jpg', 'Seattle Synchro Team', NULL, '["artistic swimming","Synchronized swimming Seattle","Kids swimming Seattle","Summer camp Seattle","Aquatic sports","Competitive swimming"]', 'Artistic Swimming Secrets: Your Top Questions Answered', 'Ever wondered how artistic swimmers smile, hold their breath, or keep hair perfect? Get answers and discover artistic swimming in Seattle!', 4, 1, '2026-05-05T19:36:20.534+00:00', '2026-05-05T19:36:21.196344+00:00', '2026-05-05T19:37:48.484963+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('cff3df59-4f61-4b09-8dab-5ed63a06845b', 'What Is Artistic Swimming? 
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('6741e3df-0fec-48c7-bc2c-b45a39b8c482', 'From Water Ballets to the Olympics: The History of Artistic Swimming', 'from-water-ballets-to-the-olympics-the-history-of-artistic-swimming', '', '<p>Artistic swimming has a history as rich and layered as the sport itself. What started as a playful experiment in movement and water has grown into one of the most demanding and visually spectacular sports in the world. If you''ve ever been curious about where this sport came from — and how it became what it is today — here''s the story.</p><hr><h3>The Early Days: Water as a Stage</h3><p>The roots of artistic swimming stretch back to the early 1900s, when performers began treating the pool less like a place to race and more like a stage.</p><p>Water ballets — choreographed swimming performances set to music — became a popular form of entertainment. Audiences were captivated by the elegance of swimmers moving in formation, and performers started experimenting with patterns, poses, and synchronized movement. It was part sport, part spectacle, and entirely unlike anything people had seen before.</p><hr><h3>Growing Into a Sport: The 1930s and 1940s</h3><p>By the 1930s and 1940s, what had started as performance art was taking shape as a competitive sport — especially in North America.</p><p>Organized competitions began to emerge, with athletes being judged on their technique, timing, and presentation. Swimming clubs and schools started offering programs dedicated to the discipline. The sport found a particularly enthusiastic following in the United States and Canada, where its combination of athleticism and artistry resonated with both participants and spectators.</p><hr><h3>Hollywood Glamour and a Wider Audience</h3><p>No history of artistic swimming would be complete without a nod to the silver screen. During the 1940s and 1950s, films featuring elaborate water ballet sequences brought the sport into living rooms and movie theaters across the country.</p><p>These performances introduced millions of people to the idea that swimming could be graceful, expressive, and breathtakingly beautiful. Competitive synchronized swimming and its Hollywood counterpart grew side by side, each raising the public profile of the other.</p><hr><h3>The Olympic Milestone: Los Angeles 1984</h3><p>The sport reached a defining moment in 1984, when synchronized swimming made its <strong>Olympic debut at the Los Angeles Games</strong>.</p><p>For athletes who had been training and competing for years, the Olympic stage was validation on the grandest scale. The world watched as swimmers demonstrated a level of strength, precision, and artistry that left audiences stunned. Many viewers who had never seen the sport before came away with a deep appreciation for just how difficult — and how beautiful — it truly was.</p><p>The Olympic inclusion marked a turning point. Investment in the sport grew, training programs expanded, and a new generation of athletes was inspired to dive in.</p><hr><h3>Decades of Evolution</h3><p>In the years following the 1984 Olympics, the sport continued to push its own boundaries. Routines became more complex, incorporating dramatic <strong>lifts</strong> that sent athletes soaring above the water''s surface. Choreography grew more sophisticated, drawing from contemporary dance, theater, and gymnastics. The athleticism required reached new heights, with competitors training for thousands of hours to master techniques that looked impossible from the outside.</p><p>The sport also expanded globally. Countries across Europe, Asia, and Latin America developed strong national programs, and international competition became increasingly fierce. Artistic swimming was no longer a North American specialty — it had become a worldwide phenomenon.</p><hr><h3>A New Name for a New Era: 2017</h3><p>In 2017, the international governing body for aquatic sports — FINA — made it official: the sport would now be known as <strong>artistic swimming</strong>.</p><p>The name change was more than a rebrand. It was a statement about what the sport had always been and where it was headed. "Synchronized" captured only one dimension of what athletes do. "Artistic" acknowledged the creativity, expression, and storytelling that are just as central to a great routine as technical precision.</p><p>The new name has slowly made its way into gyms, schools, and competition programs around the world — including right here in Seattle.</p><hr><h3>Artistic Swimming Today</h3><p>Today, artistic swimming is practiced in countries across the globe, from grassroots youth programs to elite national teams competing for Olympic medals. The sport continues to evolve, with each generation of athletes finding new ways to blend athleticism with art.</p><p>What hasn''t changed is the spirit at its core: the joy of moving together, creating something beautiful, and pushing the limits of what the human body can do in the water.</p><hr><h3>Be Part of the Story in Seattle</h3><p>At <strong>Seattle Synchro</strong>, we''re proud to carry this tradition forward right here in the Pacific Northwest. Whether your child is taking their first strokes or has been swimming for years, there''s a place for them in the artistic swimming community.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1778012986075-c6medbb2u25.jpg', 'Seattle Synchro Team', NULL, '["Artistic swimming","Synchronized swimming history","synchronized swimming Seattle","kids swimming Seattle"]', 'The History of Artistic Swimming | Seattle Synchro', 'From water ballets to the Olympic stage, discover the fascinating history of artistic swimming and how the sport has evolved over a century.', 4, 1, '2026-05-05T20:29:56.282+00:00', '2026-05-05T20:29:56.637731+00:00', '2026-05-05T20:29:56.637731+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('07802a2b-9128-463d-9c8e-59a09f8d3c47', 'How I Balanced High School and Synchro', 'how-i-balanced-high-school-and-synchro', 'Real Tips From a Student Athlete', '<p>Being a competitive artistic swimmer in high school is a lot. Early practices, long drives, homework piling up, exams sneaking up on you — it can feel like there aren''t enough hours in the day. I''ve been navigating this balancing act for a few years now, and I won''t pretend it''s always been smooth.</p><p>But I''ve figured out what works for me. And while not every tip will land the same way for everyone, I hope at least one of these makes the juggle feel a little more manageable.</p><hr><h3>Use Your Easier Classes Strategically</h3><p>Every schedule has at least one class that isn''t as intense as the others. I learned to use that time wisely — quietly chipping away at homework for harder subjects while still keeping up with the work for that class itself.</p><p>It sounds simple, but getting ahead in small pockets of time made a huge difference in how much I had left to do at night.</p><hr><h3>Sleep Beats Cramming Every Time</h3><p>If it''s getting close to midnight and I''m still not done, I stop and go to bed. Then I wake up early and finish. A little sleep is always better than none — I do better work, I retain more, and I''m not a zombie at practice.</p><p>Staying up all night before an exam almost never works. A rested brain beats a cramming session every time.</p><hr><h3>Do the Homework While It''s Fresh</h3><p>This one changed everything for me. I try to do math homework right after math class, chemistry homework right after chemistry, and so on. When the material is still fresh, the work goes so much faster.</p><p>It also means I arrive home with less on my plate — which is a much better feeling than sitting down to a mountain of assignments at 9pm.</p><hr><h3>Get to School Early</h3><p>I arrive about 45 minutes before the first bell and do homework in the library. It''s quiet, there are no distractions, and it guarantees I''m never rushing in late or stressed before the day even starts.</p><p>Those 45 minutes in the morning are some of my most productive of the entire day.</p><hr><h3>Study Outside the House</h3><p>Home is full of temptations. Suddenly the dishes need washing, a show is on, or I''m reorganizing my desk for the third time. Coffee shops and libraries cut all of that out.</p><p>When I''m in a space designed for focus, I actually focus. It sounds obvious, but it took me a while to accept that I just work better outside my own room.</p><hr><h3>Compartmentalize Your Brain</h3><p>At practice, I only think about swimming. At school, I only think about school. When I''m in the water, stressing about a homework assignment doesn''t help me — and when I''m in class, mentally replaying a routine doesn''t help me either.</p><p>Turning off one "brain" when you can''t do anything about it anyway is one of the best stress management tools I''ve found.</p><hr><h3>Stay Organized — Actually Organized</h3><p>I use a to-do list app that sorts assignments by due date and changes color as deadlines get closer. I also keep a whiteboard for exam dates and important reminders.</p><p>Nothing sneaks up on me anymore. And there''s something genuinely calming about having everything written down instead of just floating around in your head.</p><hr><h3>Adjust Your Effort Dial</h3><p>Not everything deserves 100% of your energy. An AP exam and a vocabulary quiz are not the same thing, and treating them like they are will wear you out fast.</p><p>I learned to ask myself: how much does this actually matter? Then I put in the effort that matches the answer. Saving your energy for what counts is a skill worth developing early.</p><hr><h3>Don''t Play the Suffering Olympics</h3><p>Some people love to compete over who''s the most exhausted, the most stressed, or has the most homework. It''s tempting to get pulled into that — but it kills motivation and accomplishes nothing.</p><p>Stay focused on what you need to do. Comparing your stress to someone else''s doesn''t get your homework done any faster.</p><hr><h3>A Note on Parents</h3><p>My parents took a pretty hands-off approach with my schedule, and honestly, that helped me a lot. I know that''s not the right fit for every family, but I do think it''s worth saying: extra pressure from home on top of everything else usually makes it harder to be productive, not easier.</p><p>The most helpful thing a parent can do is stay calm and trust their kid to figure it out — with support available when it''s needed.</p><hr><h3>One More Practical Thing</h3><p>Driving straight to Seattle after school instead of going home first was a game-changer for me. It cut the stress of potentially being late to practice and actually gave me more uninterrupted time for homework in the car or before practice, without backtracking eating up my evening.</p><p>Small logistics like that add up more than you''d think.</p><hr><p>Balancing high school and competitive artistic swimming isn''t easy, but it is doable — and honestly, the sport has taught me more about time management and mental discipline than any class ever has.</p><p>If you''re a student athlete at <strong>Seattle Synchro</strong> (or thinking about joining), know that you''re not alone in figuring this out. <a class="underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current" href="#">Reach out to our team</a> if you ever want to talk through what training with us looks like alongside school — we''re here to help you thrive in and out of the water.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1778013983199-068b4kykg7cg.png', 'Maya Reistad', NULL, '["artistic swimming","synchronized swimming Seattle","student athlete tips","Competitive swimming"]', 'How I Balanced High School & Synchro | Seattle Synchro', 'Seattle Synchro athlete Maya Reistad shares her real tips for balancing high school academics and competitive artistic swimming without burning out.', 4, 1, '2026-05-05T20:46:42.042+00:00', '2026-05-05T20:46:42.613352+00:00', '2026-05-05T20:46:42.613352+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('265d3bd0-3547-4134-8317-6ca8405c1ef0', 'Eat to Perform: Nutrition Tips Every Artistic Swimmer (and Their Parents) Should Know', 'eat-to-perform-nutrition-tips-every-artistic-swimmer-and-their-parents-should-know', 'Learn how artistic swimmers fuel performance with the right nutrition. Tips on carbs, protein, hydration & a sample meal plan for young athletes.', '<p>If you''ve ever watched an artistic swimming routine, whether at the Olympics or at a local meet here in Seattle, you already know how physically demanding the sport is. Swimmers are spinning, lifting, leaping, and holding their breath underwater, all while keeping a smile on their face.</p><p>What you don''t see? Everything that happens <em>before</em> they get in the pool.</p><p>Nutrition plays a huge role in how artistic swimmers train, recover, and perform. Whether your child is just starting out or training competitively, understanding the basics of fueling for this sport can make a real difference.</p><h3>Why Nutrition Matters More Than You Might Think</h3><p>Artistic swimming combines strength, flexibility, endurance, and precision, all in one routine. Athletes train for hours at a time, often several days a week. That level of activity demands real fuel.</p><p>Without the right nutrition, swimmers may feel sluggish, lose focus mid-routine, or take longer to recover between training sessions. The good news? A well-balanced approach to eating doesn''t have to be complicated.</p><h3>Carbohydrates: The Main Source of Energy</h3><p>Carbohydrates are the body''s preferred fuel, especially during high-intensity activity. When swimmers train hard, their muscles rely on glycogen (stored carbs) to keep going. Without enough carbs, energy drops fast.</p><p>For artistic swimmers, carbohydrates should make up around <strong>50–60% of daily calories</strong>. But carbs aren''t just about physical energy. They also support brain function and in a sport that requires memorizing choreography, staying in rhythm, and reacting in real time, mental sharpness matters just as much as physical stamina.</p><p><strong>Great sources of carbohydrates:</strong></p><ul><li><p>Oats, brown rice, quinoa, and whole grain bread</p></li><li><p>Sweet potatoes and regular potatoes</p></li><li><p>Bananas, berries, apples, and other fruits</p></li><li><p>Beans and lentils</p></li></ul><h3>Protein: Building and Repairing Muscles</h3><p>Every training session breaks down muscle fibers. Protein is what helps rebuild them stronger. For artistic swimmers, getting enough protein supports lean muscle development, reduces injury risk, and even helps keep the immune system strong, which matters when athletes are training hard or traveling for competitions.</p><p><strong>Timing is key.</strong> Eating protein <em>after</em> training (ideally within 30–60 minutes) helps maximize muscle recovery.</p><p><strong>Best protein sources:</strong></p><ul><li><p>Chicken, turkey, eggs, and lean beef</p></li><li><p>Greek yogurt, cottage cheese, and milk</p></li><li><p>Salmon and tuna</p></li><li><p>Tofu, edamame, and legumes</p></li></ul><h3>Healthy Fats: Sustained Energy and Joint Health</h3><p>Fats often get a bad reputation, but healthy fats are essential for artistic swimmers. They provide long-lasting energy during extended training days, support hormonal health, help the body absorb key vitamins (A, D, E, and K), and even lubricate joints which is critical in a sport built on flexibility and range of motion.</p><p><strong>Best sources of healthy fats:</strong></p><ul><li><p>Avocados and olive oil</p></li><li><p>Nuts, seeds, and nut butters</p></li><li><p>Salmon and other fatty fish</p></li></ul><p>Avoid excessive fried foods and heavily processed snacks. These can slow recovery and don''t provide lasting energy.</p><h3>Hydration: Don''t Let the Water Fool You</h3><p>Here''s something that surprises many people: swimmers can become dehydrated. Being in the pool doesn''t mean the body isn''t sweating and swimmers often underestimate how much fluid they lose during training.</p><p>Dehydration affects both physical and mental performance. When the body loses too much fluid, blood volume drops. The body prioritizes sending blood to the brain, heart, and lungs which means the working muscles receive less oxygen and fuel, leading to fatigue and reduced performance.</p><p><strong>Simple hydration habits that help:</strong></p><ul><li><p>Drink 8 oz of water with every meal</p></li><li><p>Monitor urine color (pale yellow is the goal)</p></li><li><p>Sip water or an electrolyte drink during long training sessions</p></li><li><p>Rehydrate after training with water, a sports drink, or coconut water</p></li></ul><h3>Sample Day of Eating for an Artistic Swimmer</h3><p>Here''s what a balanced day might look like:</p><p><strong>Breakfast:</strong> Oatmeal with banana, almond butter, and a glass of milk</p><p><strong>Morning Snack:</strong> Apple slices with peanut butter</p><p><strong>Lunch:</strong> Grilled chicken wrap with whole grain tortilla, avocado, lettuce, and tomato</p><p><strong>Pre-Workout Snack (1–2 hours before training):</strong> Banana with a handful of trail mix or a small yogurt parfait with granola</p><p><strong>Post-Workout Snack (within 30–60 minutes after training):</strong> Greek yogurt with berries, or a smoothie with protein powder, banana, and milk</p><p><strong>Dinner:</strong> Baked salmon with brown rice, steamed broccoli, and a drizzle of olive oil</p><p><strong>Evening Snack (if needed):</strong> Cottage cheese with fruit, or whole grain crackers with hummus</p><h3>What to Avoid</h3><p>Just as important as what to <em>eat</em> is what to <em>skip</em>. Restrictive diets (cutting out entire food groups or severely limiting calories) can seriously harm performance and development in young athletes. They lead to fatigue, nutrient deficiencies, and slower recovery.</p><p>Artistic swimmers need energy. Lots of it. The goal is to nourish the body, not restrict it.</p><h3>Building Strong Swimmers Starts Here</h3><p>At <strong>Seattle Synchro</strong>, we believe that great performance starts with taking care of the whole athlete IN and OUT of the water. Our coaches are passionate about supporting young swimmers in artistic swimming with the knowledge, training, and community they need to thrive.</p><p>Whether your child is curious about trying artistic swimming for the first time or ready to train more seriously, we''d love to welcome them to our Seattle program. <a target="_blank" rel="noopener noreferrer" class="underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current" href="https://seattlesynchro.com/programs/summer-camp">Explore our classes and summer camp options</a> and let''s build something amazing together.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1778691363010-6qeoza658rl.jpeg', 'Maria Romero', NULL, '["artistic swimming","nutrition for athletes","nutrition","aquatic sports nutrition","summer swim camp Seattle"]', 'Fueling Artistic Swimmers: Nutrition Tips | Seattle Synchro', 'Learn how artistic swimmers fuel performance with the right nutrition. Tips on carbs, protein, hydration & a sample meal plan for young athletes.', 4, 1, '2026-05-13T17:00:54.77+00:00', '2026-05-13T17:00:53.488824+00:00', '2026-05-15T20:25:10.565004+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('3e8fed02-470e-4114-8b82-27830af68e3c', 'Concussions in Artistic Swimming: Prevention and Safe Recovery', 'concussions-in-artistic-swimming-prevention-and-safe-recovery', 'Learn how to prevent, recognize, and recover from concussions in artistic swimming. Practical tips for parents, coaches, and swimmers in Seattle.', '<p>Artistic swimming is a graceful, athletic sport that combines strength, flexibility, and teamwork. While many people think of it as non‑contact, concussions are actually common in artistic swimming. Because of lifts, throws, close formations, and occasional collisions, our sport is increasingly treated like a contact sport when it comes to safety planning. Parents, coaches, and athletes in artistic swimming Seattle programs should understand how concussions happen, how to reduce risk, and what a safe recovery looks like.</p><p>What is a concussion?<br>A concussion is a mild traumatic brain injury caused by a bump, blow, or jolt to the head or body that disrupts normal brain function. Loss of consciousness is not required. Common signs include headaches, dizziness, balance problems, confusion, memory issues, and sensitivity to light or noise. In artistic swimming, these injuries can arise from head-to-head contact, impacts with teammates during lifts or routines, hitting the pool edge, or sudden whiplash from throws.</p><p>Why concussions are common in artistic swimming<br>Artistic swimming involves complex, high‑energy maneuvers performed in close proximity. During lifts and throws, athletes generate significant force, and timing or positioning errors can lead to unintended impacts. Underwater work and breath‑holding can complicate immediate recognition, and choreography often places multiple athletes within arm’s reach. All these factors increase concussion risk, which is why many programs now treat artistic swimming similarly to other contact sports when it comes to prevention and protocols.</p><p>How to reduce concussion risk<br>Safe Pool Environment<br>Keep pool decks dry, clutter‑free, and well‑lit. Check ladders, platforms, and staging areas. When rehearsing lifts or acrobatic elements near the wall or staging, add extra distance or padding to reduce the chance of impact.</p><p>Warm-Up and Conditioning<br>A thorough warm‑up builds balance, strength, and neck control. Neck and core conditioning reduce the force transmitted to the head during impacts. Proprioception and balance drills help athletes maintain spatial orientation during complex maneuvers.</p><p>Technique, Progression, and Communication<br>Teach lifts and throws step‑by‑step. Use spotters and progressions for all acrobatic elements. Emphasize clear verbal and visual cues so teammates know when to lift, rotate, or catch. Rehearse entries and exits slowly before increasing speed or height. A culture of controlled progression prevents risky improvisation.</p><p>Education for Everyone<br>All staff, athletes, and parents should learn concussion signs and response protocols. Use resources from USA Artistic Swimming and the CDC’s HEADS UP. Simulate scenarios in staff training so everyone knows how to act immediately if a head impact occurs.</p><p>What to do if a concussion is suspected<br>Immediately remove the athlete from practice and keep them out of the water. Because artistic swimming often masks symptoms (underwater work, breath control), assume any head contact could be serious. Have a trained adult supervise and arrange prompt medical evaluation from a healthcare professional experienced in sports concussions.</p><p>Initial steps:</p><ul><li><p>Stop activity and keep the swimmer comfortable and monitored.</p></li><li><p>Avoid giving medication like aspirin without medical advice.</p></li><li><p>Contact guardians and seek medical assessment without delay.</p></li></ul><p>Stage-by-stage recovery: a safe return<br>Concussion recovery follows a gradual, monitored progression. The CDC’s HEADS UP guidance and sports medicine experts recommend both physical and cognitive rest initially; limiting exercise, screen time, and schoolwork that require concentration.</p><p>Medical Clearance<br>A healthcare provider must evaluate the athlete and provide written clearance before any return to swimming or training.</p><p>Graduated Return to Activity<br>After clearance, follow a staged program:</p><ol><li><p>Light aerobic activity (walking or stationary bike) without worsening symptoms.</p></li><li><p>Sport-specific exercise that avoids head impact or heavy exertion.</p></li><li><p>Non‑contact training drills, increasing intensity.</p></li><li><p>Full practice with contact and choreography, if symptom‑free.</p></li><li><p>Return to competition.</p></li></ol><p>Each stage typically lasts at least 24 hours. If symptoms return, the athlete drops back to the previous symptom‑free step and rests. Because artistic swimming often involves complex contact and lifts, coaches should progress more conservatively than in some other sports.</p><p>Practical tips for parents and coaches</p><ul><li><p>Have a concussion action plan for practices, camps, and competitions that includes emergency contacts, removal protocols, and timelines for medical follow-up.</p></li><li><p>Foster honest reporting. Athletes should know they won’t be penalized for symptoms and that timely reporting protects their long‑term health.</p></li><li><p>Coordinate with schools to manage cognitive rest; temporary adjustments to homework, screen time, and testing can speed recovery.</p></li><li><p>Keep clear documentation of symptom progression, medical visits, and written clearance before returning to practice or events.</p></li></ul><p>Special considerations for kids swimming lessons Seattle and summer camps<br>Programs with beginners or large groups, like kids swimming lessons Seattle and summer swim camp Seattle, need extra vigilance. Young children may not describe symptoms well, so watch for behavioral changes, excessive sleepiness, or difficulty balancing. Ensure camp staff and lesson instructors receive concussion training and have direct communication plans with guardians.</p><p>Conclusion<br>Concussions in artistic swimming are more common than many realize because of the sport’s close‑contact lifts, throws, and complex choreography. Treating artistic swimming like a contact sport through education, safe technique, well organized pool spaces, and conservative return‑to‑play procedures, helps to keep athletes safe and supports full recovery. Prioritizing brain health ensures swimmers can enjoy artistic swimming for years to come.</p><p>Ready to learn more? Visit <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/">Seattle Synchro</a> to learn more about our club and programs.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1780948793148-zvrei37495a.JPG', '', NULL, '["artistic swimming","synchronized swimming Seattle","competitive swimming","aquatic sports","Swimming"]', 'Concussions in Artistic Swimming: Prevention & Care', 'Learn how to prevent, recognize, and recover from concussions in artistic swimming. Practical tips for parents, coaches, and swimmers in Seattle.', 4, 1, '2026-06-15T16:52:37.738+00:00', '2026-05-13T17:04:47.742865+00:00', '2026-06-15T16:52:26.435766+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('dd5acd55-ed77-44e3-859a-9e5304533b70', 'Swim Lessons vs Artistic Swimming: Which Is Right for Your Kid?', 'swim-lessons-vs-artistic-swimming-which-is-right-for-your-kid', 'Not sure whether to choose swim lessons or artistic swimming for your child in Seattle? Here is what each offers and how to pick the right fit.', '<p>If you are a Seattle parent researching summer activities for your child, you have probably come across both traditional swim lessons and artistic swimming camps. Since both happen in the water, they can seem similar at first glance, but they actually serve very different purposes.</p><p>One important thing to know is that our artistic swimming summer camps are not swim lessons. Campers are expected to already feel comfortable in the water and have basic swimming skills before joining. Once children have that foundation, artistic swimming opens the door to an entirely different experience.</p><p>Here is a breakdown to help you understand the difference and decide what may be the best fit for your child.</p><hr><h3>What Swim Lessons Are Designed For</h3><p>Traditional swim lessons focus on water safety and foundational swimming skills. Children learn how to float, tread water, breathe properly, and swim basic strokes with confidence. For young children or beginners, these lessons are essential.</p><p>The structure is usually individual and skill-based. Kids progress through levels as they master specific techniques and water safety milestones. The goal is confidence and competence in the water.</p><p>For many children, swim lessons are the first step in building a lifelong relationship with aquatic sports.</p><hr><h3>What Happens After Kids Learn to Swim?</h3><p>Once children are comfortable swimming independently, many families start looking for the next challenge. Some kids enjoy lap swimming, while others crave something more creative, social, and dynamic.</p><p>That is where artistic swimming comes in.</p><p>Artistic swimming takes the swimming foundation children already have and combines it with music, choreography, teamwork, athleticism, and performance. Instead of simply swimming from one end of the pool to the other, athletes learn how to move with precision and creativity in the water.</p><p>They work together as a team, learn routines set to music, build strength and flexibility, and perform for an audience at the end of camp. It becomes not only a sport, but also an artistic and social experience.</p><hr><h3>Why Kids Love Artistic Swimming</h3><p>Artistic swimming combines many elements children already enjoy:</p><ul><li><p>Swimming</p></li><li><p>Dance</p></li><li><p>Gymnastics</p></li><li><p>Music</p></li><li><p>Performance</p></li><li><p>Teamwork</p></li></ul><p>For kids who already know how to swim, it often feels exciting and completely different from traditional lessons. Every day introduces new skills, creative movement, and team activities that keep campers engaged and motivated.</p><p>Many children who feel bored in regular swim lessons suddenly become energized when swimming is connected to music, routines, and performance.</p><p>It is also an incredible sport for building:</p><ul><li><p>Strength and endurance</p></li><li><p>Confidence</p></li><li><p>Coordination</p></li><li><p>Discipline</p></li><li><p>Creativity</p></li><li><p>Mental toughness</p></li><li><p>Team connection</p></li></ul><hr><h3>Is Your Child Ready for Artistic Swimming Camp?</h3><p>Our camps are beginner-friendly when it comes to artistic swimming experience, but swimmers should already:</p><ul><li><p>Feel comfortable in deep water</p></li><li><p>Be able to swim independently</p></li><li><p>Have basic water confidence</p></li><li><p>Be comfortable putting their face underwater</p></li></ul><p>No artistic swimming experience is required at all. We teach all the artistic swimming skills during camp.</p><p>For many families, artistic swimming becomes the perfect “next step” after swim lessons.</p><hr><h3>Why Summer Camp Is the Best Way to Try It</h3><p>Committing to a full sports season can feel overwhelming, especially when your child is trying something completely new. Summer camp offers a low-pressure, fun introduction to the sport.</p><p>In just one week, campers:</p><ul><li><p>Learn foundational artistic swimming skills</p></li><li><p>Work together as a team</p></li><li><p>Practice movements to music</p></li><li><p>Build confidence in the water</p></li><li><p>Perform a short routine for family and friends</p></li></ul><p>The goal is not perfection. Our goal is to help kids discover a love for the sport while feeling successful, supported, and excited to learn.</p><p>Many swimmers leave camp asking to come back before the final showcase is even over.</p><h3>So Which One Should You Choose?</h3><p>Choose swim lessons if your child is still learning basic swimming skills or building water confidence.</p><p>Choose artistic swimming camp if your child already knows how to swim and is ready for a more creative, athletic, and team-oriented experience in the water.</p><p>And if your child loves music, movement, teamwork, or performing, artistic swimming may become their favorite part of the summer.</p><hr><p>Seattle Synchro offers artistic swimming classes and summer camps in Seattle for kids ages 6 to 11, with no prior experience required beyond basic water comfort. If you are ready to see what your child can do in the water, we would love to have them join us this summer. Visit our <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">summer camp</a> page to check dates and reserve a spot.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1779422007377-0o62v8pc9cer.webp', '', NULL, '["Artistic Swimming","Summer Swim Camp Seattle","Kids Swimming Lessons Seattle","Summer Swim Camp PNW"]', 'Swim Lessons vs Artistic Swimming for Seattle Kids', 'Not sure whether to choose swim lessons or artistic swimming for your child in Seattle? Here is what each offers and how to pick the right fit.', 3, 1, '2026-05-22T03:56:14.67+00:00', '2026-05-22T03:35:56.438375+00:00', '2026-05-22T06:43:02.351382+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('631e2198-bd23-4a45-a74f-be9ff7732cfd', 'What Is Artistic Swimming? The Water Sport Your Kid Will Love This Summer in Kirkland', 'what-is-artistic-swimming-the-water-sport-your-kid-will-love-this-summer-in-kirkland', '', '<blockquote><p>Picture this: your child is gliding through crystal-clear water, perfectly in sync with her teammates, her movements matching every beat of the music playing overhead. She flips upside down, holds a stunning pose with her legs straight up in the air, then surfaces with the biggest smile you''ve ever seen. That''s artistic swimming — and it might just be the sport that changes your child''s summer forever.</p></blockquote><p>If you''ve never heard of artistic swimming before, you''re not alone. Most Seattle families discover it by accident, after watching the Olympics on TV, a friend''s recommendation, or stumbling across our summer camp listing. And almost every single parent has the same first reaction: <strong>"I can''t believe this exists and we didn''t know about it sooner."</strong></p><p>So let''s fix that. In this guide, we''ll walk you through everything you need to know: what artistic swimming actually is, how it differs from regular swim lessons, what skills your child will build, and why our <a target="_blank" rel="noopener noreferrer" class="cta-inline" href="https://seattlesynchro.com/programs/summer-camp"><strong>Seattle Summer Camp ↗</strong></a> is the perfect way for kids to try it for the first time.</p><blockquote><h3><strong>Ready to try it this summer?</strong></h3><p>Our Artistic Swimming Summer Camp is designed for first-timers. No experience needed, just a love of water and basic safety swimming skills.</p><p><a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">Reserve Your Child''s Spot ↗</a></p></blockquote><h2><strong>So, What Exactly Is Artistic Swimming?</strong></h2><p>Artistic swimming formerly known as synchronized swimming, is an Olympic sport that blends competitive swimming with choreography, music, gymnastics, and acrobatics. Athletes perform elaborately choreographed routines, either solo, as a duet, or as a team of up to eight, all while staying perfectly in sync with each other and with the music.</p><p>If you''ve ever watched figure skating and thought, "I wish this was in the water," congratulations, you''ve basically described artistic swimming. The athleticism is real, the artistry is stunning, and the community is one of the most welcoming in all of youth sports.</p><h2><strong>What Will My Child Actually Learn?</strong></h2><p>This is where parents are consistently surprised. They expect their child to learn to swim in formation. What they discover is that artistic swimming develops a comprehensive set of skills that benefit kids far beyond the pool.</p><p></p><h4><strong>Strength &amp; Endurance</strong></h4><p>Treading water for minutes at a time gradually builds the endurance needed to stay afloat for hours. Artistic swimming develops core and leg strength through constant resistance from the water, often faster than almost any other sport. Athletes combine cardio, strength, flexibility, and breath control all at once, creating exceptional full-body conditioning.</p><h4><strong>Rhythm &amp; Musicality</strong></h4><p>Syncing movements to music develops a natural sense of timing, rhythm, and musical interpretation that carries into dance, music, and everyday coordination.</p><h4><strong>Teamwork</strong></h4><p>Every routine requires complete trust in teammates. Swimmers learn to lift, support, and rely on one another in very real ways while working toward a shared goal.</p><h4><strong>Artistic Expression</strong></h4><p>From facial expressions to elegant arm movements, young athletes learn to communicate emotion and tell stories through movement — a rare and valuable skill.</p><h4><strong>Spatial Awareness</strong></h4><p>Performing above, at, and below the water surface builds exceptional body awareness, coordination, and motor control in three-dimensional space.</p><h4><strong>Confidence &amp; Stage Presence</strong></h4><p>Every practice includes opportunities to perform and be seen. Kids who may be shy in the classroom often gain confidence, presence, and self-expression in the water.</p><p></p><h4><strong>Mental Toughness &amp; Resilience</strong></h4><p>Artistic swimming builds exceptional mental strength and resilience. Athletes learn to push their physical limits while performing in the absence of oxygen, manage pressure in high-stress situations, and continue striving for excellence in a sport built on precision and near-perfect execution. Through challenges, setbacks, and demanding training, swimmers develop discipline, perseverance, and the ability to push through discomfort with confidence and determination.</p><h2><strong>How Is Artistic Swimming Different from Swim Lessons?</strong></h2><p>This is the question we hear most often from new parents. Both happen in a pool. Both involve kids in swimsuits. But the two activities have almost nothing else in common.</p><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" style="text-align: left;"><p><strong>Category</strong></p></th><th colspan="1" rowspan="1" style="text-align: left;"><p><strong>Traditional Swim Lessons</strong></p></th><th colspan="1" rowspan="1" style="text-align: left;"><p><strong>Artistic Swimming</strong></p></th></tr><tr><td colspan="1" rowspan="1"><p><strong>Primary goal</strong></p></td><td colspan="1" rowspan="1"><p>Water safety &amp; stroke technique</p></td><td colspan="1" rowspan="1"><p>Sport, artistry &amp; performance</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>What kids do</strong></p></td><td colspan="1" rowspan="1"><p>Swim laps, practice strokes</p></td><td colspan="1" rowspan="1"><p>Choreography, figures, acrobatics</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Social element</strong></p></td><td colspan="1" rowspan="1"><p>Individual focus</p></td><td colspan="1" rowspan="1"><p>Deep team bonding</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Performances</strong></p></td><td colspan="1" rowspan="1"><p>None (skill-based)</p></td><td colspan="1" rowspan="1"><p>Regular showcases </p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Music &amp; creativity</strong></p></td><td colspan="1" rowspan="1"><p>None</p></td><td colspan="1" rowspan="1"><p>Central to every session</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Prerequisite</strong></p></td><td colspan="1" rowspan="1"><p>None</p></td><td colspan="1" rowspan="1"><p>Basic comfort in water</p></td></tr></tbody></table><h2><strong>Is Artistic Swimming Right for My Child?</strong></h2><p>Artistic swimming tends to attract a certain kind of kid, but that "certain kind" is broader than most parents expect. Here''s a quick guide:</p><table style="min-width: 50px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" style="text-align: left;"><p><strong>Your child loves…</strong></p></th><th colspan="1" rowspan="1" style="text-align: left;"><p><strong>Artistic swimming offers…</strong></p></th></tr><tr><td colspan="1" rowspan="1"><p>Dance or gymnastics</p></td><td colspan="1" rowspan="1"><p>The same artistry and performance, in the water</p></td></tr><tr><td colspan="1" rowspan="1"><p>Swimming but is bored by lap training</p></td><td colspan="1" rowspan="1"><p>A completely new way to experience the pool</p></td></tr><tr><td colspan="1" rowspan="1"><p>Team sports and making friends</p></td><td colspan="1" rowspan="1"><p>One of the tightest-knit team environments in youth sports</p></td></tr><tr><td colspan="1" rowspan="1"><p>Music and rhythm</p></td><td colspan="1" rowspan="1"><p>Routines choreographed specifically to music they help choose</p></td></tr><tr><td colspan="1" rowspan="1"><p>Being on stage / performing</p></td><td colspan="1" rowspan="1"><p>A family showcase at the end of every camp week</p></td></tr><tr><td colspan="1" rowspan="1"><p>Trying something nobody else does</p></td><td colspan="1" rowspan="1"><p>A unique sport that will make them the coolest kid at school</p></td></tr></tbody></table><h2><strong>Why Our Summer Camp Is the Perfect First Step</strong></h2><p>If you''re curious but not ready to commit to a full season, our Artistic Swimming Summer Camp in Washington was designed exactly for you.</p><p>Our camp is intentionally designed to be both beginner-friendly and highly technical at the same time. We understand that for many families, this is their very first introduction to artistic swimming. Our goal is not simply to teach skills for a week, it’s to create a positive, exciting experience that makes kids fall in love with the sport.</p><p>Swimmers are introduced to real artistic swimming techniques in a supportive, encouraging environment led by experienced coaches and athletes. Every day combines skill-building, creativity, teamwork, fitness, and fun in a way that keeps kids engaged and confident in the water.</p><p>Rather than focusing on perfection or competition, we focus on helping each swimmer feel successful, challenged, and inspired. We want campers to leave the week stronger, more confident, and excited to come back for more.</p><blockquote><p><a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">Reserve Your Child''s Spot ↗</a></p></blockquote><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1779418937186-p44h5t6aqds.JPEG', 'Seattle Synchro Team', NULL, '["what is artistic swimming","summer activities Seattle kids","summer camp Seattle 2026"]', 'What Is Artistic Swimming? The Sport Bellevue, Kirkland Kids Love', 'Discover artistic swimming, the Olympic water sport combining swimming, dance, and acrobatics. See why Washington state families are signing up this summer.', 5, 1, '2026-05-22T03:03:50.826+00:00', '2026-05-22T03:02:43.638976+00:00', '2026-05-22T06:34:04.303909+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('8bd8ea00-0cb8-4039-a348-1086179075ab', 'More Than a Sport: The Psychology Behind Artistic Swimming', 'more-than-a-sport-the-psychology-behind-artistic-swimming', 'More Than a Sport: The Psychology Behind Artistic Swimming', '<p>When most people think of artistic swimming, they picture graceful movements, sparkling costumes, and synchronized routines. But there''s something even more powerful happening beneath the surface — and it has nothing to do with technique.</p><p>Artistic swimming is one of the most mentally demanding sports in the world. And that''s exactly what makes it so transformative for kids and teens.</p><hr><h3>It Takes More Than a Strong Body</h3><p>Yes, artistic swimming requires fitness, flexibility, and breath control. But ask any coach or athlete, and they''ll tell you the same thing: the mental game is just as important.</p><p>Swimmers learn to stay calm while holding their breath underwater. They learn to keep smiling even when their muscles are burning. They train their brains to stay focused, execute under pressure, and bounce back from mistakes.</p><p>These aren''t just swimming skills. They''re life skills.</p><hr><h3>Building Confidence in the Water (and Beyond)</h3><p>One of the most beautiful things we see at Seattle Synchro is how quickly athletes grow in confidence.</p><p>For many kids, joining an artistic swimming program is the first time they''ve had to perform in front of others. It can feel scary at first. But with every practice, every routine, and every competition, something shifts.</p><p>They start to trust themselves. They start to believe they can do hard things.</p><p>That quiet confidence doesn''t stay in the pool. It shows up in the classroom, in friendships, and in how kids handle challenges they never expected to face.</p><hr><h3>Teamwork Is the Heart of the Sport</h3><p>Artistic swimming is unique because you can''t succeed alone. Every movement is tied to your teammates. If one person is off, the whole routine changes.</p><p>This teaches young swimmers something that''s hard to learn anywhere else: <em>your actions affect the people around you.</em></p><p>Kids in synchronized swimming programs learn to communicate, to listen, and to be accountable — not because a coach told them to, but because the water makes it obvious. The team only looks beautiful when everyone is working together.</p><p>For parents searching for kids'' swimming lessons in Seattle that build more than just strokes, artistic swimming offers something rare: a sport built entirely on cooperation.</p><hr><h3>Resilience: What Happens When It Goes Wrong</h3><p>No routine is perfect. No competition is without nerves. And that''s the point.</p><p>Artistic swimming gives athletes a safe place to fail, reset, and try again. They learn that a mistake in practice doesn''t define them. They learn to shake it off and keep going — with a smile, no less.</p><p>Over time, this builds something psychologists call resilience: the ability to recover from difficulty. Research consistently shows that kids who develop resilience early are better equipped to handle stress, anxiety, and setbacks throughout their lives.</p><p>At Seattle Synchro, we think of every tough practice as a resilience-building opportunity. It''s not about being perfect. It''s about not giving up.</p><hr><h3>Focus and Mindfulness — Without the Meditation App</h3><p>Here''s something most people don''t know: artistic swimming naturally trains mindfulness.</p><p>When you''re underwater, you can''t hear your coach. You can''t check your phone. You can''t think about tomorrow''s homework. You have to be <em>completely present</em> — aware of your body, your breath, your teammates, and the music all at once.</p><p>This kind of focused attention is something adults pay good money to develop. For kids in artistic swimming programs, it''s just another Tuesday at practice.</p><hr><h3>A Sport That Sees the Whole Child</h3><p>At Seattle Synchro, we believe athletic swimming programs should care about the whole athlete — not just their splits and scores.</p><p>We see kids come in shy and leave confident. We see teammates become best friends. We see young athletes discover what they''re capable of when they stop being afraid of the water and start trusting themselves.</p><p>Whether you''re looking for summer swim camp in Seattle, year-round training, or just a new activity to try, artistic swimming might be exactly what your child needs — not just for their body, but for their mind.</p><hr><p><strong>Ready to dive in?</strong> We''d love to welcome your family to Seattle Synchro. Explore our classes, summer camps, and programs at <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com">www.seattlesynchro.com</a> and see what artistic swimming in Seattle is all about.</p><p>/</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1778690997800-33o85o6u9uu.jpg', 'Seattle Synchro Team', NULL, '["artistic swimming","kids swimming Seattle","Aquatic sports"]', 'The Mental Side of Artistic Swimming | Seattle Synchro', 'More Than a Sport: The Psychology Behind Artistic Swimming', 3, 1, '2026-06-08T19:58:42.561+00:00', '2026-05-13T16:58:48.428203+00:00', '2026-06-08T19:58:39.766242+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('6e6c3439-03de-4813-8bd4-4a7eeae5eba2', 'How Is Artistic Swimming Judged? A Simple Guide for Curious Parents and New Fans', 'how-is-artistic-swimming-judged-a-simple-guide-for-curious-parents-and-new-fans', '', '<p>If you watched artistic swimming at the Olympics, you probably had two reactions. First, amazement. Second, confusion about where those scores came from.</p><p>You are not alone. Scoring is the number one question we hear from families new to the sport here in Seattle.</p><p>The good news is that the system makes a lot of sense once you break it into pieces. Here is a plain English guide.</p><h2>Two Panels of Judges, Plus a Third Group Watching</h2><p>Every routine is scored by two separate panels of five judges each.</p><p>One panel scores <strong>execution</strong>, meaning how cleanly the swimmers perform their skills. The other panel scores <strong>artistic impression</strong>, meaning how well the routine works as a piece of performance.</p><p>Behind them sit the technical controllers, who are not scoring beauty at all. They are checking the rulebook.</p><h2>The Elements Panel: How Well Did They Do It?</h2><p>Before a competition, each team submits something called a coach card. It lists every skill, or element, the swimmers plan to perform and the exact order they will perform them in.</p><p>Think of it like a menu handed to the judges in advance. There is no hiding a mistake, because the judges already know what is coming.</p><p>Each element carries a set degree of difficulty, or DD. A basic lift is worth less than a complicated one with a twist and a throw.</p><p>The five judges score each element from 0 to 10 in quarter point steps. The highest and lowest scores get thrown out, the middle three are averaged, and that average is multiplied by the degree of difficulty.</p><p>Add up every element and you have the elements score.</p><p>This is why coaches think so carefully about routine design. A hard skill performed sloppily can score lower than a simpler skill performed beautifully.</p><h2>The Artistic Impression Panel: Did It Move You?</h2><p>The second panel of five judges scores three things.</p><p><strong>Choreography and musicality</strong> covers creativity, variety, use of the whole pool, and how well the movement matches the music.</p><p><strong>Performance</strong> covers expression, confidence, and presence. This includes the walk on before the swimmers even hit the water.</p><p><strong>Transitions</strong> covers the movement that links the big skills together, including strokes, propulsion, and pattern changes.</p><p>Transitions used to be an afterthought. Starting in 2026 they carry the most weight of the three, close to half of the artistic impression score. Simple filler swimming between highlights no longer works.</p><h2>Technical Controllers: The Rule Checkers</h2><p>Two groups of three technical controllers watch every routine.</p><p>The first group compares what actually happens in the water against that coach card. If a team declares a double twist and delivers a single, the difficulty gets adjusted.</p><p>The second group watches synchronization. A minor timing error costs 0.1 points. An obvious one costs 0.5. A major error, such as a swimmer missing a movement entirely, costs 3.0 points.</p><h2>So How Is the Final Score Calculated?</h2><p>It is simpler than it looks:</p><p><strong>Elements score + artistic impression score - penalties = final score</strong></p><p>That is it. Difficulty and cleanliness on one side, artistry on the other, minus anything the controllers flag.</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1785631014538-yyuqqul6pzj.png" alt="artistic-swimming-scoring-infographic.png"><h2>Does My Child Get Judged Like This Right Away?</h2><p>No, and this is the part that puts most parents at ease.</p><p>Beginners in our kids swimming lessons in Seattle are not competing under Olympic rules. Younger swimmers work on figures, which are individual skills performed slowly so judges can assess body position and control.</p><p>Athletes move up gradually. Age group competition uses a simplified version of the same framework, so by the time a swimmer reaches the junior level, none of it feels unfamiliar.</p><p>Plenty of our swimmers never compete at all. They come for the strength, the breath control, the friendships, and the fun of building something with a team.</p><h2>Why Understanding Scoring Makes Watching More Fun</h2><p>Once you know what the judges are looking for, meets stop being a blur.</p><p>You start noticing whether the team is actually covering the pool. You catch the moment a lift goes higher than the one before. You see a swimmer hold her expression through a skill that is clearly exhausting.</p><p>It turns you from a confused spectator into a parent who knows exactly why that routine earned what it earned.</p><h2>Come See It in Person</h2><p>Artistic swimming rewards a rare combination of athleticism, artistry, and teamwork, and there is nothing quite like watching a child discover they are capable of it.</p><p>Seattle Synchro welcomes swimmers of all experience levels, from first timers who just want to try something new to athletes ready to compete. Our summer swim camp in Seattle is a relaxed way to test the waters before committing to a season.</p><p>Curious whether artistic swimming is right for your family? Take a look at our class schedule or reach out with questions. We would love to meet you at the pool.</p><p>REFERENCES:</p><p>Flores, M., &amp; Marmet, C. (2026, January 28). <em>Rule updates for the 2026 season: What''s changing and what isn''t</em>. Inside Synchro. <a target="_blank" rel="noopener noreferrer" href="https://insidesynchro.org/2026/01/28/rule-updates-for-the-2026-season-whats-changing-and-what-isnt/">https://insidesynchro.org/2026/01/28/rule-updates-for-the-2026-season-whats-changing-and-what-isnt/</a></p><p>NBC Olympics. (2024). <em>Artistic swimming 101: Olympic scoring, rules and regulations</em>. <a target="_blank" rel="noopener noreferrer" href="https://www.nbcolympics.com/news/artistic-swimming-101-olympic-scoring-rules-and-regulations">https://www.nbcolympics.com/news/artistic-swimming-101-olympic-scoring-rules-and-regulations</a></p><p>USA Artistic Swimming. (n.d.). <em>Judges</em>. Retrieved August 1, 2026, from <a target="_blank" rel="noopener noreferrer" href="https://www.usaartisticswim.org/resources/judges">https://www.usaartisticswim.org/resources/judges</a></p><p>World Aquatics. (2023). <em>Artistic swimming manual for judges, technical controllers, referees</em>. <a target="_blank" rel="noopener noreferrer" href="https://resources.fina.org/fina/document/2023/06/16/87f71841-01d3-4ecc-943c-ef67954f5c2d/AQUA-AS-MANUAL_15-JUNE-23.pdf">https://resources.fina.org/fina/document/2023/06/16/87f71841-01d3-4ecc-943c-ef67954f5c2d/AQUA-AS-MANUAL_15-JUNE-23.pdf</a></p><p>World Aquatics. (2026). <em>Artistic swimming rules</em>. <a target="_blank" rel="noopener noreferrer" href="https://www.worldaquatics.com/artistic-swimming/rules">https://www.worldaquatics.com/artistic-swimming/rules</a></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1785632355856-8xvqpav9zed.webp', 'Seattle Synchro Team', NULL, '["Artistic swimming seattle","artistic swimming score","artistic swimming kids"]', 'How Is Artistic Swimming Judged? A Parent''s Guide', 'Wondering how artistic swimming is scored? Learn how judges rate execution and artistic impression, plus what it means for young swimmers in Seattle.', 4, 1, '2026-08-02T01:00:21.276+00:00', '2026-08-02T01:02:04.977993+00:00', '2026-08-02T01:02:04.977993+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('9e2ba2b6-fcd6-4ec8-b862-0af60ed0336e', '5 Reasons Our Artistic Swimming  Summer Camp Is the Best Week of Your Child''s Summer', '5-reasons-our-artistic-swimming-summer-camp-is-the-best-week-of-your-childs-summer', 'We know you have options. Washington has no shortage of summer camps, swim programs, and activity weeks for kids. So here is why families keep choosing ours, and why their kids keep asking to come back.', '<hr><h2>1. They Learn a Real Olympic Sport in One Week</h2><p>Not arts and crafts. Not free swim. Your child will spend the week learning the actual foundations of artistic swimming, the same sport performed at the Olympics, with coaches who have competed at a high level and genuinely love teaching it.</p><hr><h2>2. They Leave With a Real Foundation, Not Just a Fun Week</h2><p>Five days is not enough to perform a full routine. But it is enough for your child to learn how to perform a short routine and move differently in the water.</p><p>By Friday, they will understand how artistic swimming works, know basic figures and positions, and have a feel for moving with a team. That foundation is what makes kids want to continue in the fall. And most of them do.</p><hr><h2>3. No Experience Needed At All</h2><p>Your child does not need to have taken artistic swimming before. They do not need to be on a swim team. They just need to be safe and comfortable in the water.</p><p>We built this camp specifically for first-timers. The entire week is designed to take a child with zero background and give them a real foundation — and a real love for the sport — by the time they leave.</p><hr><h2>4. They Leave With New Skills, Confidence, and a Team</h2><p>Your child will leave camp with new skills, new confidence, and a group of kids they actually want to see again in the fall. One of the most common things parents tell us is that their child made some of their closest summer friendships here.</p><hr><h2>5. Get a True Sense of the Sport Before Committing</h2><p>In just one week, your child will get a real sense of what artistic swimming is like. This helps families make an informed decision about whether to commit to a full season, which runs year-round from September through June.</p><p>It’s the best way to explore the sport without pressure, while still experiencing the structure, teamwork, and excitement of a full training environment.</p><hr><h2>Camp Details at a Glance</h2><p>Artistic swimming <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">summer camp</a> in Seattle, is open to boys and girls ages 6 to 11. No prior experience is required. Our experienced coaches provide a supportive environment where campers build a solid foundation in the sport by the end of the week.</p><p>Spots are limited and fill up quickly. If this sounds like the right week for your child, the best step is to register early and secure their place in camp.</p><p>Ready to sign them up? Head to our <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">summer camp</a> page to see more details. </p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1779423699134-siudxloizji.webp', 'Seattle Synchro Team', NULL, '["Kids Summer Activities Seattle","Summer Camp Bellevue","Artistic Swimming kirkland"]', '5 Reasons Our Artistic Swimming Summer Camp Stands Out', 'Looking for the best summer camp in Bellevue for your kid? Here are 5 reasons our artistic swimming camp is the week they will never forget.', 2, 1, '2026-05-22T04:09:23.685+00:00', '2026-05-22T04:09:24.143258+00:00', '2026-05-22T07:16:42.818091+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('8ab85ef8-ed11-4bc2-9e8a-7ed291eb594b', 'SafeSport in Artistic Swimming: What Every Parent Should Know', 'safesport-in-artistic-swimming-what-every-parent-should-know', '', '<p>When families look for a swimming program, they want more than great coaching and fun routines. They want to know their child is safe, respected, and in good hands. At Seattle Synchro, athlete well-being is one of our highest priorities, and that commitment is backed by a nationwide program called SafeSport.</p><p>Here''s what SafeSport is, why it matters, and what it means for your family.</p><h3>What Is SafeSport?</h3><p>SafeSport is a comprehensive education and prevention program designed to protect athletes from misconduct, abuse, harassment, bullying, hazing, and other harmful behavior. It operates through the U.S. Center for SafeSport, a nonprofit organization established to address these issues across Olympic and Paralympic sports.</p><p>In artistic swimming, SafeSport is supported and required by USA Artistic Swimming (USAAS), the national governing body for the sport. It applies to everyone who works with athletes, not just coaches.</p><h3>Who Is Required to Complete SafeSport Training?</h3><p>USA Artistic Swimming requires SafeSport training for all members who interact with athletes. This includes coaches, staff, board members, volunteers, chaperones, judges, and adult athletes.</p><p>The training is not a one-time requirement. Members must complete regular refresher courses to stay current and compliant. This ongoing commitment helps ensure that everyone working in artistic swimming is educated, informed, and held to a consistent standard of conduct.</p><h3>What Does SafeSport Actually Cover?</h3><p>SafeSport is more than a single online course. It''s a framework of education, policies, and accountability measures. Key components include:</p><p><strong>Minor Athlete Abuse Prevention Policies (MAAPP):</strong> These policies define clear boundaries for how adults should interact with minor athletes. They cover everything from one-on-one communications to travel and locker room guidelines.</p><p><strong>Mandatory Reporting:</strong> Adults in the sport are required to understand how and when to report suspected misconduct. Reporting can be done through USA Artistic Swimming or directly through the U.S. Center for SafeSport.</p><p><strong>Background Checks:</strong> Many adults who work or volunteer with teams are required to pass background checks before getting involved. This helps identify potential risks before they arise.</p><p><strong>Ongoing Training:</strong> SafeSport education must be maintained over time. Annual refresher courses keep participants up to date as policies and best practices evolve.</p><h3>A Culture Built on Respect</h3><p>Beyond the policies and training requirements, USA Artistic Swimming promotes a broader culture of athlete wellness. This includes an Athlete Bill of Rights, which outlines every swimmer''s right to safe training, respectful treatment, and personal well-being.</p><p>The goal is not just compliance, it''s creating an environment where athletes feel supported, heard, and valued. That means encouraging open conversations between parents, athletes, coaches, and officials about what a safe and healthy experience looks like.</p><p>Artistic swimming is a sport built on trust and teamwork. Those values should extend beyond the pool.</p><h3>What This Means at Seattle Synchro</h3><p>At Seattle Synchro, we take these standards seriously. Our coaches and staff are trained in SafeSport requirements, and we are committed to creating a space where every swimmer, whether they are just starting out in kids swimming lessons in Seattle or training at a competitive level, feels safe and respected.</p><p>We believe that a great artistic swimming experience should be joyful, challenging, and completely free from fear or harm.</p><h3>Questions? We''d Love to Connect.</h3><p>If you''re exploring artistic swimming in Seattle for your child and want to learn more about how we prioritize safety, our coaches are happy to talk. Whether you''re curious about our summer camp in Seattle, our recreational classes, or our competitive programs, we''d love to hear from you.</p><p>Visit our website to learn more about <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/">Seattle Synchro</a> or reach out to register for an upcoming session. We can''t wait to welcome your family to the pool.</p><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1780438457569-mnbg7nakvs.jpg', 'Seattle Synchro', NULL, '["Artistic swimming","Safety","Safe sports","Synchronized swimming","Youth sports"]', NULL, 'Learn how SafeSport protects young artistic swimmers through training, background checks, and clear policies. Seattle Synchro is committed to athlete safety.', 3, 1, '2026-06-02T22:10:33.475+00:00', '2026-06-02T22:10:11.582206+00:00', '2026-06-02T22:15:35.941142+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('b1d846c6-b5be-4890-8815-eedb146a8db7', 'From First Splash to Full Season: Understanding the Programs at Seattle Synchro', 'understanding-the-categories-at-seattle-synchro', '', '<p>So your child loves the water, but regular swim lessons feel a little... ordinary. Maybe you caught a few minutes of artistic swimming at the Olympics and thought, <em>wait, kids can do that?</em> The answer is yes. And if you''re in the Seattle area, there''s a program built just for them.</p><p>At Seattle Synchro, swimmers of all ages and experience levels can explore artistic swimming, the sport formerly known as synchronized swimming that blends athleticism, creativity, and teamwork in the water. Whether your child is just getting their feet wet or ready to compete at a regional meet, there''s a place for them here.</p><p>Here''s a breakdown of every program category so you can find the right fit.</p><h3>What Is Artistic Swimming, Exactly?</h3><p>Artistic swimming is a competitive aquatic sport that combines swimming, dance, and gymnastics, all performed in sync with music. Swimmers develop serious strength, flexibility, and breath control, all while making it look effortless (and yes, while smiling).</p><p>It''s one of the few sports that blends athletic rigor with artistic expression, which makes it a uniquely rewarding experience for kids who love both movement and performance. It''s also deeply team-oriented, which means swimmers build lasting friendships alongside real athletic skills.</p><h3>Starting Out: Recreational &amp; Intro Programs</h3><p>Not ready to dive into competition? No problem. Seattle Synchro''s introductory programs are designed to make artistic swimming accessible, fun, and completely pressure-free.</p><p><strong>Sea Stars</strong> is the perfect entry point for younger swimmers, typically kids aged 5 to 10, who already know basic swim skills but have never tried artistic swimming before. In this program, swimmers start learning the foundational building blocks of the sport: sculling (the hand movements that keep swimmers afloat and in control), body positioning, and how to move together in time with music.</p><p>The environment is low-key and encouraging. There are no competitions, no pressure, just kids in the water discovering something new and having a great time doing it. If your child has been looking for a fun alternative to traditional kids swimming lessons in Seattle, this is a wonderful place to start.</p><h3>Ready to Compete: Novice &amp; Intermediate Teams</h3><p>Once a swimmer has learned the basics and wants more of a challenge, the competitive side of Seattle Synchro opens up. The <strong>Novice and Intermediate teams</strong> are a natural next step for swimmers who are ready to commit to a season of training and take part in local competitions.</p><p>At this level, athletes start working on more advanced choreography, technical figures, and the kind of precise teamwork that artistic swimming is known for. Practice happens throughout the season, and swimmers get their first real taste of what it means to perform as part of a team — in front of judges and an audience.</p><p>This is a big step for young athletes, and it builds confidence in ways that go well beyond the pool.</p><h3>The Full Path: Age Group Competitive Teams</h3><p>For swimmers who are ready to fully commit to the sport, Seattle Synchro''s <strong>Age Group competitive teams</strong> offer a structured, year-round training experience. These teams follow the USA Artistic Swimming framework and are grouped by age; typically 12 &amp; Under, 13–15, and 16–19, with Junior and Senior categories for older teen athletes.</p><p>Swimmers at this level train consistently through the year, focusing on synchronicity, artistic impression, and technical skill. They compete at regional and national meets, which means they''re part of a broader community of artistic swimmers across the country.</p><p>Year-round competitive swimming is a serious commitment, but for the right athlete, it''s also incredibly rewarding. Many swimmers at this level say the sport becomes one of the most defining parts of their childhood and teen years.</p><h3>How Do You Know Which Program Is Right for Your Child?</h3><p>Here''s a simple way to think about it:</p><ul><li><p><strong>New to the sport? Start with Sea Stars.</strong> It''s the friendliest on-ramp to artistic swimming Seattle has to offer.</p></li><li><p><strong>Has some experience and wants a challenge? Novice or Intermediate teams</strong> are a great fit.</p></li><li><p><strong>Ready to train year-round and compete?</strong> Age Group teams will give them everything they''re looking for.</p></li></ul><p>Not sure where your child fits? The Seattle Synchro team is happy to help you figure it out.</p><h3>Come Find Your Place in the Water</h3><p>Artistic swimming is one of those sports that surprises people. Once they see what it actually involves, they''re hooked. It''s athletic, creative, musical, and deeply collaborative. And it''s happening right here in Seattle.</p><p>Whether you''re looking for a fun summer swim camp in Seattle, a new after-school activity, or a competitive path for a driven young athlete, Seattle Synchro has something for your family.</p><p><strong>Visit </strong><a target="_blank" rel="noopener noreferrer" href="http://SeattleSynchro.org"><strong>SeattleSynchro.org</strong></a><strong> to explore current programs, upcoming sessions, and registration information and get ready to make a splash!</strong></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1782151172619-cpvd1tf8wth.JPG', 'Seattle Synchro Team', NULL, '["artistic swimming Seattle","synchronized swimming Seattle","kids swimming lessons Seattle","competitive swimming","aquatic sports","summer swim camp Seattle"]', 'Artistic Swimming Programs at Seattle Synchro Explained', 'From beginner classes to competitive teams, explore every artistic swimming program at Seattle Synchro and find the perfect fit for your child.', 4, 1, '2026-06-22T17:59:47.993+00:00', '2026-06-22T17:46:40.217462+00:00', '2026-06-22T17:59:48.181743+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('285ce0f8-e1f5-4a8d-9fb6-848331cfd186', 'Meet the Olympians Who Got Their Start at Seattle Synchro', 'seattle-synchro-olympic-athletes', '', '<p>When you watch artistic swimming at the Olympics, it''s easy to feel like those athletes exist in a different universe. But here''s something pretty special: several of them got their start right here, in Seattle pools, in programs a lot like ours.</p><p>Seattle Synchro has been part of the Seattle artistic swimming community for decades. In that time, the program has produced multiple Olympians, including gold and silver medalists. Here''s their story.</p><h3>A Golden Legacy: 1984 Los Angeles</h3><p>Seattle Synchro''s Olympic story starts back in 1984, when Tracy Ruiz-Conforto and Candy Costie-Burke won Olympic gold medals at the Los Angeles Games.</p><p>Their coach, Charlotte Davis, was later inducted into the International Swimming Hall of Fame for her contributions to the sport. That gold-medal foundation helped establish Seattle as a serious hub for artistic swimming talent, long before most Americans had even heard of the sport.</p><h3>Keeping the Tradition Alive: 2008 and Beyond</h3><p>The Olympic legacy didn''t stop in the ''80s. Jillian Penner represented the program at the 2008 Summer Olympics, continuing a tradition of Seattle-trained athletes competing on the world''s biggest stage.</p><p>Over the years, Seattle Synchro swimmers have also gone on to earn spots on US National Teams and compete for elite university programs across the country.</p><h3>Paris 2024: A New Generation Shines</h3><p>Most recently, two Seattle-area athletes made history together. Audrey Kwon and Keana Hunter, both trained locally, were part of the nine-member U.S. team that took silver at the 2024 Paris Olympics—marking the first time in 16 years that Team USA had qualified for the Olympics in artistic swimming. <a target="_blank" rel="noopener noreferrer" class="group/tag relative h-[18px] rounded-full inline-flex items-center overflow-hidden -translate-y-px cursor-pointer" href="https://www.kuow.org/stories/seattle-trained-synchronized-swimmers-take-silver-at-paris-olympics">KUOW</a><a target="_blank" rel="noopener noreferrer" class="group/tag relative h-[18px] rounded-full inline-flex items-center overflow-hidden -translate-y-px cursor-pointer" href="https://www.king5.com/article/sports/olympics/locals-team-usa-artistic-swimming-paris-olympics/281-8fab4cb2-429c-4920-9ed3-a631ab641aed">King 5</a></p><p>Their achievement mattered for another reason too. The sport had recently transformed from the graceful "water ballet" style of past decades into something far more acrobatic and athletic, with routines now including gravity-defying lifts and throws judged with a difficulty scale similar to gymnastics. <a target="_blank" rel="noopener noreferrer" class="group/tag relative h-[18px] rounded-full inline-flex items-center overflow-hidden -translate-y-px cursor-pointer" href="https://www.kuow.org/stories/seattle-trained-synchronized-swimmers-take-silver-at-paris-olympics">KUOW</a></p><p>Watching two Seattle-trained swimmers help lead that new era felt like a full-circle moment for the local artistic swimming community.</p><h3>What This Means for Young Swimmers in Seattle</h3><p>You don''t need to have Olympic dreams to enjoy artistic swimming. But it''s inspiring to know that the same pools, coaches, and community your child could join have already helped shape Olympic athletes.</p><p>Whether your swimmer wants to compete one day or simply loves being creative in the water, they''ll be training in a program with real roots in the sport''s biggest stage.</p><h3>Common Questions About Seattle''s Olympic Connection</h3><p><strong>Do I need to be an elite athlete to join a program with Olympic history?</strong><br>Not at all. Programs welcome swimmers at every level, from beginners in kids swimming lessons Seattle families love, to advanced competitive athletes.</p><p><strong>Can kids really go from a local program to the Olympics?</strong><br>It''s happened multiple times. Several Seattle-trained swimmers have gone on to Junior National Teams, US National Teams, and even the Olympics itself.</p><p><strong>Is artistic swimming the same sport it was in the ''80s?</strong><br>Not exactly. The sport has become far more athletic and acrobatic over time, though the artistry and teamwork that made it special remain at its heart.</p><h3>Start Your Own Journey</h3><p>You never know where a first swim class might lead. Explore Seattle Synchro''s classes and summer swim camp Seattle programs, and give your child a chance to train in a community with a genuine Olympic legacy.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1785786551182-zuub8zk97oa.jpg', 'Seattle Synchro Team ', NULL, '["Olympics","Seattle Synchro","Artistic Swimming","Swimming in Seattle","Kids swimming Lessons","Synchronized swimming"]', 'Meet Seattle Synchro''s Olympic Athletes | Seattle Synchro', 'From 1984 gold medalists to 2024 Paris silver medalists, discover the Olympic athletes who got their start at Seattle Synchro artistic swimming.', 3, 1, '2026-08-18T16:21:43.922+00:00', '2026-08-03T19:49:16.485882+00:00', '2026-08-18T16:21:26.036467+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('26f544fe-0eaf-4723-929d-e848277e2fec', 'What''s the Difference Between Synchronized Swimming and Artistic Swimming?', 'whats-the-difference-between-synchronized-swimming-and-artistic-swimming', '', '<p>If you''ve searched online for <strong>synchronized swimming</strong>, you''ve probably also come across the term <strong>artistic swimming</strong>. Are they different sports? Did one replace the other? And why do people still use both names?</p><p>The short answer is simple. <strong>They are the same sport.</strong> The name officially changed in 2017, but many people still know it as synchronized swimming. Even today, parents, athletes, and even Olympic fans often use both terms interchangeably.</p><p>Let''s look at how the sport has evolved and why the name changed.</p><h2>From Water Ballet to Synchronized Swimming</h2><p>Long before it appeared in the Olympics, the sport was often called <strong>water ballet</strong>. During the early 1900s, performers combined swimming, dance, and music to create beautiful routines in pools. These performances focused on grace, creativity, and synchronized movement.</p><p>As the sport became more competitive, the name <strong>synchronized swimming</strong> became widely adopted. It emphasized the athletes'' ability to perform precise movements together while staying perfectly in time with the music.</p><p>For decades, synchronized swimming became the name recognized around the world, especially after it joined the Olympic Games in 1984.</p><h2>Why Did the Name Change to Artistic Swimming?</h2><p>In 2017, the international governing body for aquatic sports officially renamed synchronized swimming to <strong>artistic swimming</strong>.</p><p>The goal was not to create a new sport. Instead, the new name better reflected everything athletes do in the water. Artistic swimming combines athletic strength, flexibility, endurance, creativity, musical interpretation, and teamwork. The routines are just as much about artistic expression as they are about synchronization.</p><p>The name also aligns with other judged sports such as artistic gymnastics and artistic skating, where athletic performance and artistic presentation are equally important.</p><p>Although the official name changed, many people continue to search for synchronized swimming because that''s the term they grew up hearing.</p><h2>Why Do People Still Say Synchronized Swimming?</h2><p>Changing the name of a sport takes time.</p><p>Many parents remember watching synchronized swimming during the Olympics and naturally continue using that name. Television commentators, news articles, and local programs also used synchronized swimming for decades, making it familiar to several generations.</p><p>Today, you''ll hear both terms depending on who you''re talking to. That''s completely normal.</p><p>Whether someone searches for <strong>synchronized swimming Seattle</strong> or <strong>artistic swimming Seattle</strong>, they''re looking for the same incredible sport.</p><h2>Why Kids Love Artistic Swimming</h2><p>Artistic swimming offers much more than learning routines in the water. Young athletes develop skills that benefit them both in and out of the pool.</p><p>Some of the biggest benefits include:</p><ul><li><p>Building confidence through performance.</p></li><li><p>Improving strength and flexibility.</p></li><li><p>Developing teamwork and communication.</p></li><li><p>Learning musicality and rhythm.</p></li><li><p>Creating lasting friendships in a supportive environment.</p></li></ul><p>Because athletes work together toward common goals, many children quickly discover a strong sense of belonging within their team.</p><h2>Is Artistic Swimming Right for Beginners?</h2><p>Absolutely.</p><p>Many families assume artistic swimming is only for experienced swimmers or competitive athletes. In reality, beginners are welcome, and most programs introduce skills step by step.</p><p>Children learn water confidence, basic swimming techniques, simple artistic movements, and teamwork in a fun and encouraging environment.</p><p>If your child enjoys swimming, dancing, gymnastics, or simply trying something new, artistic swimming can be a wonderful fit.</p><p>Families searching for <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/recreational">kids swimming lessons Seattle</a> often discover that artistic swimming provides a unique combination of fitness, creativity, and fun.</p><h2>Discover Artistic Swimming with Seattle Synchro</h2><p>Whether you call it <strong>water ballet</strong>, <strong>synchronized swimming</strong>, or <strong>artistic swimming</strong>, the heart of the sport has always been the same. It is about athleticism, creativity, teamwork, and having fun in the water.</p><p>At Seattle Synchro, we welcome swimmers of different ages and experience levels. From beginner classes to competitive programs and our exciting <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp"><strong>summer swim camp Seattle</strong></a>, there''s an opportunity for every child to discover this unique Olympic sport.</p><p>If you''re curious about artistic swimming or want your child to try something different, we''d love to help you get started. Explore our programs, meet our welcoming community, and see why so many families in Seattle are falling in love with artistic swimming.<br><br><strong>References</strong></p><ul><li><p>Encyclopaedia Britannica. (s.f.). <em>Synchronized swimming</em>. <a target="_blank" rel="noopener noreferrer" href="https://www.britannica.com/sports/synchronized-swimming">https://www.britannica.com/sports/synchronized-swimming</a></p></li><li><p>International Olympic Committee. (s.f.). <em>Artistic Swimming</em>. <a target="_blank" rel="noopener noreferrer" href="https://olympics.com">https://olympics.com</a></p></li><li><p>USA Artistic Swimming. (s.f.). <em>About USA Artistic Swimming</em>. <a target="_blank" rel="noopener noreferrer" href="https://www.usaartisticswim.org">https://www.usaartisticswim.org</a></p></li><li><p>World Aquatics. (2017). <em>FINA Bureau approves artistic swimming name change</em>. <a target="_blank" rel="noopener noreferrer" href="https://www.worldaquatics.com">https://www.worldaquatics.com</a></p></li></ul><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1785627464931-sdyc0msrjj.png', 'Seattle Synchro Team', NULL, '["artistic swimming","Synchronized Swimming","Aquatic Sports"]', 'Artistic Swimming vs Synchronized Swimming Explained', 'Learn why synchronized swimming became artistic swimming, what changed, and why both names still matter. Discover the sport with Seattle Synchro.', 3, 1, '2026-08-01T23:38:08.918+00:00', '2026-08-01T23:39:43.786998+00:00', '2026-08-07T10:50:45.228358+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('8b225179-2831-45f4-9481-3daabf2a8c32', 'Can Artistic Swimming Be Recreational? Yes—Here''s How', 'can-artistic-swimming-be-recreational-yesheres-how', 'When most people picture artistic swimming, they think of the Olympics. Sequined suits, dramatic music, perfectly synchronized routines. It looks intense and it can be.</p><p>But here''s something a lot of parents don''t realize: artistic swimming doesn''t have to be competitive at all. It can simply be fun.', '<h3>What Recreational Artistic Swimming Looks Like</h3><p>Recreational artistic swimming is all about building skills and confidence in a low-pressure environment. Kids learn basic strokes, treading water techniques, and simple synchronized movements with friends.</p><p>There are no judges. No scores. No pressure to win.</p><p>Instead, the focus is on movement, music, teamwork, and just having a good time in the water. It''s a wonderful way to introduce kids to the sport without the intensity of competitive training.</p><h3>Who Is It For?</h3><p>Recreational artistic swimming is great for:</p><ul><li><p>Kids who love to swim but aren''t interested in competing</p></li><li><p>Beginners who want to try something new and creative</p></li><li><p>Swimmers who enjoy performing and teamwork, without the pressure of meets</p></li><li><p>Families looking for a fun alternative to typical kids swimming lessons Seattle families are used to</p></li></ul><p>You don''t need any prior experience. Most recreational classes welcome swimmers of many different skill levels, and instructors adjust routines so every child can participate and succeed.</p><h3>Why Try Artistic Swimming Instead of Traditional Lessons?</h3><p>Traditional swim lessons focus on strokes and safety skills, both incredibly important. Artistic swimming builds on those basics but adds something extra: creativity.</p><p>Kids get to be expressive. They learn choreography, work with teammates, and build confidence performing in front of others. It''s swimming, dance, and teamwork rolled into one.</p><p>Many families find that kids who weren''t excited about typical swim practice light up when they discover artistic swimming Seattle programs that let them move to music and be part of a team.</p><h3>Does Recreational Mean "Not Serious"?</h3><p>Not at all. Recreational swimmers still learn real skills: body control, breath holding, treading water, and basic synchronized patterns.</p><p>The difference is the goal. Recreational programs prioritize enjoyment and skill-building over competition results. Some kids stick with the recreational track for years simply because they love it. Others use it as a stepping stone before deciding if they want to try competitive synchronized swimming later on.</p><p>Either path is completely valid, there''s no "right" way to enjoy the sport.</p><h3>A Great Fit for Summer Camp</h3><p>Because it''s playful, social, and doesn''t require prior experience, artistic swimming is a natural fit for summer programs. A summer swim camp Seattle kids attend might include:</p><ul><li><p>Basic artistic swimming skills like sculling and floating</p></li><li><p>Simple group routines set to music</p></li><li><p>Games that build water confidence</p></li><li><p>A fun, low-stakes end-of-week showcase for family and friends</p></li></ul><p>It''s a great way for kids to try something new during summer break, make friends, and stay active in the water, all without the commitment of a competitive season.</p><h3>Common Questions Parents Ask</h3><p><strong>Does my child need swim team experience?</strong><br>Nope! Many recreational swimmers are trying artistic swimming for the very first time.</p><p><strong>Is it safe for beginners?</strong><br>Yes. Instructors tailor each class to the swimmers'' comfort and skill level, and safety always comes first.</p><p><strong>Can recreational swimmers move to competitive teams later?</strong><br>Absolutely. Many competitive synchronized swimmers actually started out in a recreational program before deciding to pursue the sport more seriously.</p><h3>Try It for Yourself</h3><p>Artistic swimming isn''t just for future Olympians; it''s for any kid who loves the water and wants to try something a little different. Whether your child is looking for a new hobby, a fun summer activity, or just a break from traditional swim lessons, recreational artistic swimming might be the perfect fit.</p><p>Curious what a class looks like in person? Explore Seattle Synchro''s recreational classes and summer camp options, and see why so many Seattle families are diving into this joyful, creative sport.</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1785785464880-y8jln4p5avk.jpeg', 'Maria Romero', NULL, '["Artistic swimming","Summer Camps","Sports","Recreation","Bellevue","Swimming","Synchronized Swimming"]', 'Can Artistic Swimming Be Recreational? | Seattle Synchro', 'Think artistic swimming means Olympic-level training? Learn how kids in Seattle can enjoy synchronized swimming just for fun, no competition required.', 3, 1, '2026-08-11T17:32:11.649+00:00', '2026-08-03T19:14:28.271902+00:00', '2026-08-11T17:32:02.228771+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('cccdebc7-1b13-4fdf-8e0c-1f37f87e88f1', 'Boys in Artistic Swimming: A Growing Sport for Everyone', 'boys-in-artistic-swimming-a-growing-sport-for-everyone', '', '<p>Have you noticed how much aquatic sports are changing? For a long time, people thought synchronized swimming was only for girls. That is not the case anymore. Today, boys are jumping into the pool and changing the sport completely.</p><p>If you are looking for kids swimming lessons Seattle, you might want to think outside the box. Artistic swimming offers a totally unique challenge for active boys. It is a sport that builds strength, teaches teamwork, and welcomes everyone. Here is why more boys are trying it out.</p><h2>Real Male Stars Making History</h2><p>For years, boys were not allowed to compete at the highest levels of this sport. That all changed recently. The rules were updated to allow men to compete in team routines at the Olympic Games. This was a huge step forward for equality in sports.</p><p>American swimmer Bill May is a true legend in the sport. He trained for decades and fought hard to let men compete on the world stage. Because of his hard work, the doors opened for a whole new generation.</p><p>Other global stars like Giorgio Minisini from Italy and Dennis Gonzalez Boneu from Spain are also showing the world what male athletes can do. They bring incredible power and style to their routines. When young boys see these athletes on television, they realize this sport is for them too.</p><h2>Physical Advantages for Boys</h2><p>Artistic swimming is a serious workout. It requires the lungs of a runner and the power of a gymnast. Boys who join this sport develop amazing physical abilities that help them in all areas of life.</p><p>One big advantage is core strength. Swimmers have to hold their bodies high out of the water without touching the bottom. This builds strong abdominal and back muscles. Boys who practice this sport often have incredible posture and balance.</p><p>Another huge benefit is explosive power. In team routines, athletes often lift and throw their teammates into the air. Male athletes naturally develop strong shoulders and legs to help push those heavy lifts higher. It is a fantastic way to build strong muscles safely in the water.</p><h2>Mental Benefits and Teamwork</h2><p>The benefits go far beyond physical strength. Artistic swimming teaches boys how to focus under pressure. They have to memorize long routines and count the music perfectly while holding their breath. This takes a lot of mental discipline.</p><p>It is also a deeply team-oriented sport. Every person in the water must work together to make the routine successful. Boys learn how to communicate well, trust their teammates, and solve problems as a group.</p><p>Stepping into a sport that has historically been for girls also builds great confidence. These young athletes learn to ignore old stereotypes. They just focus on working hard and enjoying their time in the water with their friends.</p><h2>A Great Way to Start</h2><p>You might be wondering how to get your son involved. The best way is to try it out in a fun and relaxed setting. A <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/recreational">recreational artistic swimming program</a> in Seattle is the perfect introduction for beginners.</p><p>The <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/recreational">recreational program</a> let kids learn the very basic skills without any pressure to compete. They can try floating, sculling, and simple upside-down moves. They will also make new friends and see if they enjoy the teamwork aspect of the sport.</p><p>Once they feel comfortable, they can easily transition into a regular class. Our artistic swimming Seattle programs are designed to help all beginners feel right at home. We teach everything step by step.</p><h2>Join the Seattle Synchro Family</h2><p>We believe that the pool is a place for everyone. We are very proud to welcome boys to our teams. If your son loves the water and wants a fun new challenge, we would love to meet him.</p><p><a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com">Seattle Synchro</a> offers classes for all ages and skill levels. Visit our <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com">website</a> to check out our schedule and register for a beginner class today!</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1788201444657-2ltn7dks0fo.jpg', 'Seattle Synchro Team', NULL, '["boys artistic swimming","inclusive youth sports Seattle","kids swimming lessons Seattle","male artistic swimmers"]', 'Boys in Artistic Swimming: A Growing Sport for Everyone', 'Artistic swimming is no longer just for girls. Discover how boys are diving into this inclusive youth sport in Seattle to build strength and teamwork.', 3, 1, '2026-08-31T18:37:36.997+00:00', '2026-08-31T18:38:22.876117+00:00', '2026-08-31T18:38:22.876117+00:00');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('fbc2febe-e7e2-4eb8-af98-bee44cfa2173', '5 Realistic Things Parents Should Know About Artistic Swimming', '5-realistic-things-parents-should-know-about-artistic-swimming', '', '<p>Watching synchronized swimming at the Olympics is magical. The athletes make incredibly difficult movements look effortless and graceful. Naturally, many children watch those performances and immediately want to try dancing in the water.</p><p>If you are currently looking into kids swimming lessons Seattle, you might be considering this beautiful sport. However, the day-to-day reality of practice is a bit different from the Olympic finals. Here are five realistic things every parent should know before signing up for artistic swimming.</p><h2><strong>1. They Need Basic Swimming Skills First</strong></h2><p>While your child does not need to be a gymnastics expert, they cannot be a complete beginner in the pool. Artistic swimming requires a solid foundation of water safety. Athletes spend a lot of time in deep water, so they need to feel completely confident without touching the bottom.</p><p>At <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/">Seattle Synchro</a>, we require our new swimmers to meet a few basic prerequisites. Swimmers must be safe in the water and swim independently. Specifically, they need to complete two laps of freestyle or crawl, two laps of breaststroke, and one lap of backstroke.</p><p>They also must be able to float on their back independently for ten seconds and tread water for twenty seconds. If your child is not quite there yet, traditional swimming lessons are a great first step. Once they build that stamina, they will be fully ready to dive into our <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs">artistic swimming Seattle programs</a>.</p><h2><strong>2. The Learning Curve Requires Patience</strong></h2><p>This sport is a marathon, not a sprint. Learning to control your body upside down in the water takes time and a lot of core strength. Beginners spend weeks mastering basic sculling techniques and eggbeater kicks before they ever learn a full routine.</p><p>Parents should expect a learning curve. Your child will not be performing Olympic-level lifts in their first month. They will, however, build incredible resilience and discipline.</p><p>Progress happens in small, rewarding milestones. Celebrating those little victories keeps kids motivated as they build their foundational strength.</p><h2><strong>3. Attendance Is Crucial for the Team</strong></h2><p>In many recreational sports, missing a practice here and there is not a big deal. Artistic swimming is a bit different. The core of the sport is the team routine, which relies heavily on exact formations and synchronization.</p><p>If one swimmer is missing, the entire pattern is thrown off. Teammates cannot practice their lifts or spacing effectively. This makes consistent attendance incredibly important.</p><p>When you join a team, you are making a commitment to the other athletes. This teaches children a profound sense of responsibility and teamwork. They quickly learn that their presence matters to the success of their friends.</p><h2><strong>4. The Reality of "Competition Hair"</strong></h2><p>If your child decides to compete, you will eventually meet <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/athletes/knoxing">Knox gelatin</a>. To keep hair perfectly in place underwater, athletes paint unflavored gelatin onto their tight buns. It is a completely safe and traditional part of the sport.</p><p>Applying the gelatin takes practice, and washing it out requires very warm water and plenty of conditioner. Meet mornings often turn into fun bonding sessions where parents help each other with hair and makeup. It is a unique part of the culture that you will quickly learn to navigate.</p><h2><strong>5. Parents Are Part of the Team Too</strong></h2><p>Artistic swimming requires a realistic time investment from families. Introductory classes might only meet once a week. However, as your child progresses, practice times will increase.</p><p>Parents are the backbone of this sport. You will become an expert at carpooling, packing high-energy snacks, and managing wet towels. Furthermore, local competitions rely heavily on parent volunteers to run the music, organize the deck, and judge figures.</p><p>This parent involvement creates a deeply supportive community. You will spend a lot of time in the bleachers with other families. Many parents find that they make just as many friends as their children do.</p><h3><strong>Come Swim With Us in Seattle</strong></h3><p>Artistic swimming is a deeply rewarding journey that builds strength, teamwork, and lifelong confidence. If your child meets the basic swimming requirements, a <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">summer artistic swim camp</a> Seattle is the perfect, low-pressure way to try it out.</p><p><a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/">Seattle Synchro </a>is proud to offer programs that guide families through every step of this amazing sport. We would love to welcome you to our community. Visit our website to check out our upcoming <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/beginner">beginner programs</a> and <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/contact-us">register today!</a></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/blog/1788199819455-6bg7mgoto4m.jpg', 'Seattle Synchro Team', NULL, '["kids swimming Seattle","synchronized swimming Seattle","youth sports","parenting tips"]', '5 Realistic Things Parents Should Know About Artistic Swimming', 'Considering artistic swimming for your child? From basic swim prerequisites to parent commitments, here is a realistic guide to starting the sport in Seattle.', 4, 1, '2026-08-31T18:11:40.9+00:00', '2026-08-31T18:11:36.497849+00:00', '2026-08-31T18:50:55.58938+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('5be2505d-2021-461a-bdf4-086d5d23a507', 'Another successful meet at Classic Invitational this past weekend', 'another-successful-meet-at-classic-invitational-this-past-weekend', '', '<p>All club athletes attended Classic Invitational this past weekend, joined by Aquasonics Artistic Swim Club, Evergreen Artistic Swimming, MAC Synchro, Pacific Waves Synchro, and Rocky Mountain Splash.</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014191186-hzrmutr4x8t.png" alt="image.png"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014199577-coidwt9p3mw.png" alt="image.png"><p></p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014208808-fos1c00luk7.png" alt="image.png"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014340471-noov1bvenwq.jpg', 'event', 'Quan Zhou', NULL, '["Synchro","Competition"]', NULL, NULL, 1, 1, '2026-05-05T20:52:00.125+00:00', '2026-05-05T20:52:00.60693+00:00', '2026-05-05T20:52:49.31707+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('34c9513e-929a-41df-9d14-7c6d6041c0c1', 'Junior & Senior Nationals recap', 'junior-senior-nationals-recap', '', '<p>Our junior team wrapped up an incredible week at Junior &amp; Senior Nationals!</p><p>So much fun, growth, and teamwork every step of the way—we’re proud of everything we learned and accomplished together.</p><p>Now it’s time for our Youth and 12U athletes to take the national stage next week. Let’s go, team!&nbsp;💪💙💚</p><p></p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014613040-9eklsrp151.png" alt="image.png"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014603885-61yro3dskzv.jpg', 'event', 'Quan Zhou', NULL, '[]', NULL, NULL, 1, 1, '2026-05-05T20:57:05.722+00:00', '2026-05-05T20:57:05.861795+00:00', '2026-05-05T20:57:16.690142+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('b6307a4c-50d0-473e-b831-38997194a7a0', 'Youth National and 12U Invitational is a wrap!', 'youth-national-and-12u-invitational-is-a-wrap', '', '<p>Congratulations to our 12U A and Youth A &amp; B teams for representing our club at the national stage!!&nbsp;</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014676933-ooqeqh98di.png" alt="image.png"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014683247-d6nqkpku5pt.png" alt="image.png"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014688638-z2u8apqefa.png" alt="image.png"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778014732997-1dwjgl9tpxe.jpg', 'event', 'Quan Zhou', NULL, '["Competition"]', NULL, NULL, 1, 1, '2026-05-05T20:59:10.335+00:00', '2026-05-05T20:58:36.598314+00:00', '2026-05-13T17:02:25.13925+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('562ce92e-fac0-4c99-81b5-0743c1ad8dd7', 'West Zone Success, Our Teams Are Heading to Nationals!', 'a-successful-weekend-in-west-zone', 'Seattle Synchro athletes gave an incredible performance at Pacific Regionals! See how our teams did and what''s coming up next.', '<p>What a weekend for Seattle Synchro! Our 12U, Youth, and Junior teams competed at the West Zone Championship and delivered performances that made the entire Seattle Synchro family incredibly proud. The hard work, early mornings, and hours in the pool absolutely showed.</p><p>Every athlete stepped up when it counted — from our youngest 12U swimmers bringing energy and precision to the deck, to our Youth and Junior teams executing with the kind of focus and artistry that turns heads at every meet. This is what artistic swimming in Seattle looks like, and we couldn''t be more excited about what''s ahead.</p><p>Next stop: <strong>Nationals!</strong> 🙌 Want to follow the journey in real time? <strong>Follow us on Instagram </strong><a target="_blank" rel="noopener noreferrer" class="underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current" href="https://instagram.com/seattlesynchro"><strong>@SeattleSynchro</strong></a> — we share competition updates, behind-the-scenes moments, and everything happening in our aquatic community. Don''t miss a thing! 🤽‍♀️</p><hr><p>Ahí tienes el primer post real generado con el prompt. Funcionó bien con muy poca información — imagínate si el cliente agrega más detalles como resultados específicos, medallas, o el nombre de la ciudad donde fue el meet. El output sería aún más rico.</p><p></p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778002217566-2kdwuh7uvsl.jpg" alt="westzone-youthb_058724-tsm-med.jpg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778726066394-41s6vidumfz.png" alt="image.png"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778726084949-yyztdly62s.png" alt="image.png"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778726094920-hly7cvep6g.png" alt="image.png"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1778002089138-64sjaqqacrt.jpg', 'event', 'Quan Zhou', NULL, '["competition"]', 'Seattle Synchro Shines at Pacific Regionals 2025', 'Our 12U, Youth, and Junior teams crushed it at West Zone! Big performances, proud moments, and now eyes on Nationals. Read all about it.', 1, 1, '2026-05-05T18:32:35.132+00:00', '2026-05-05T17:30:30.196129+00:00', '2026-05-14T02:35:09.605098+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('94eb9fcc-c850-47fd-bafc-8b85d7771bd7', 'Seattle Synchro Dominates at Charlotte Davis Region A 2026', 'seattle-synchro-dominates-at-charlotte-davis-region-a-2026', 'Regionals 2026', '<p>We are beyond proud! Seattle Synchro had an absolutely spectacular showing at the 2026 Charlotte Davis Region A Intermediate and Age Group Artistic Swimming Championship in Portland, Oregon on May 16 and 17. Our athletes competed with heart, precision, and pure joy, and the results speak for themselves. This was a weekend the entire Seattle Synchro community will remember.</p><p>Our teams brought home incredible placements across every division. The Intermediate groups finished 2nd and 3rd, while our 12 and Under A team claimed 1st place and 12 and Under B took 2nd. Youth A earned 1st, Youth C grabbed 3rd, and Youth B finished 4th. And our Junior team was unstoppable, landing 1st place in both Technical and Free Team. As a result of these outstanding performances, we have officially qualified our teams, all solos, and duets across every category for the Junior Olympics in Michigan, the biggest competition of the year. What an achievement for artistic swimming in Seattle!</p><p>Follow @SeattleSynchro on Instagram to celebrate with us, relive the highlights, and stay up to date on our journey to the Junior Olympics and every artistic swimming competition ahead. The best is yet to come! </p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1779821574486-tbhozb48td.jpg', 'competition', 'Patricia Camaran', NULL, '["synchro","artisticswimming","competition","regionals","USAAS","USA","washington","seattle","water"]', 'Seattle Synchro Dominates at Charlotte Davis Region A 2026', 'Seattle Synchro earns top placements at the 2026 Charlotte Davis Region A Championship in Portland and qualifies for Junior Olympics in Michigan!', 1, 1, '2026-05-26T18:59:52.001+00:00', '2026-05-26T18:54:03.42107+00:00', '2026-05-26T20:23:11.243985+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('bf723071-9137-4a1a-948b-2bb5ef6b9e1d', 'Seattle Synchro Shines at Blossom Invitational 2026', 'seattle-synchro-shines-at-blossom-invitational-2026', 'Seattle Synchro''s novice and intermediate teams delivered an incredible performance at Blossom Invitational 2026. Celebrate with us this Sunday!', '<p></p><p>What an incredible way to close out the season! Seattle Synchro''s novice and intermediate teams took to the water at the Blossom Invitational 2026 and brought home results that made the entire community proud. This was artistic swimming Seattle at its very best.</p><p>Competing at Olympic View Swim &amp; Tennis Club Outdoor Pool in Normandy Park on May 31, our novice teams captured 1st and 2nd place, while our intermediate teams earned 1st and 3rd place. With these outstanding results, both groups officially wrapped up their competitive season in style. We are so proud of every athlete for their hard work, dedication, and growth throughout the year. Keep training with that same discipline because the next season is right around the corner!</p><p>Now it''s time to celebrate together! This Sunday, we invite all families, friends, and the broader artistic swimming Seattle community to join us for our Celebration Swim in Newport Hills Swim and Tennis Club at 10am. Athletes will perform the routines they competed this season, and we''ll be recognizing our most outstanding swimmers of the year. You won''t want to miss it! Follow us on Instagram at @SeattleSynchro to stay up to date on all upcoming events, competitions, and behind-the-scenes moments from our team.</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1780419588672-ba6hsebg23i.jpeg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1780419504538-i8x7mysl61i.jpeg"><p></p><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1780419032556-4vflcy1dgph.JPG', 'competition', 'Patricia Camaran', NULL, '["synchro","competition","blossom2026","artisticswimming","washington","synchromeet"]', 'Seattle Synchro Shines at Blossom Invitational 2026', 'Seattle Synchro''s novice and intermediate teams delivered an incredible performance at Blossom Invitational 2026. Celebrate with us this Sunday!', 1, 1, '2026-06-02T17:00:09.269+00:00', '2026-06-02T17:00:09.861254+00:00', '2026-06-02T17:02:26.970536+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('74e1d992-6731-4357-b1c4-e05ebfa67b9f', 'Seattle Synchro Closes Out the Season in Style at Celebration Swim 2026!', 'seattle-synchro-closes-out-the-season-in-style-at-celebration-swim-2026', '', '<p>What a season, Seattle Synchro family! On Sunday, June 7th, we gathered at Newport Hills Swim and Tennis Club to celebrate everything our athletes and coaches have accomplished this year. From our youngest Novice swimmers to our Junior-Senior competitors, every team came together for an unforgettable end-of-season celebration.</p><p>The day was packed with special moments. We honored our top athletes in each category, and gave heartfelt recognition to the swimmers and coaches who are graduating in 2026 and heading off to college. A huge congratulations to Isabella Lin, named Seattle Synchro''s Athlete of the Year 2026! We also launched a brand-new Club Hall of Fame, and were so proud to induct our very first honoree, coach Yuki Maekawa, who brings an extraordinary 44 years of coaching experience to our club. None of this would be possible without our incredible coaches, judges, and parents whose dedication to artistic swimming in Seattle inspires us every single day. Thank you all!</p><p>The celebration may be over, but the season never really stops at Seattle Synchro! We invite everyone to join us for our <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/summer-camp">Summer Camp </a>and <a target="_blank" rel="noopener noreferrer" href="https://seattlesynchro.com/programs/elite-clinic">Elite Clinic</a> 2026. Follow us on Instagram at @SeattleSynchro to stay up to date on registration details, upcoming events, competitions, and all the behind-the-scenes moments that make our community so special. </p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1780944315988-e3tpsffy8sr.jpg"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1780942199126-u2kw7u0mu7n.JPG', NULL, 'Patricia Camaran', NULL, '["synchro","celebrationswim2026","artisticswimming","show","seattle","seattlesynchro"]', 'Seattle Synchro Celebration Swim 2026 – Season Wrap-Up', 'Seattle Synchro wrapped up an incredible season at Celebration Swim 2026! Awards, graduations, and a brand-new Hall of Fame honor made this one for the books.', 1, 1, '2026-06-08T18:45:57.106+00:00', '2026-06-08T18:45:51.547723+00:00', '2026-06-08T18:45:57.294627+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('d1b73ecb-232a-47db-bb3b-b9f390bc3667', 'Seattle Synchro Elite Clinic 2026 | July Training Event', 'seattle-synchro-elite-clinic-2026-july-training-event', ' The Elite Clinic 2026 Is Almost Here — Get Ready to Make Waves!', '<p>Big things are coming to Seattle Synchro this summer! We are thrilled to announce our Elite Clinic 2026, a four-day intensive training experience designed to push our swimmers to the next level and explore exciting new directions in artistic swimming. This is one event you do not want to miss!</p><p>The clinic runs July 27th through July 30th at Newport Hills Swim and Tennis Club, welcoming 12U, Youth, and Junior athletes. We are incredibly excited to have Tammy McGregor and Paula Klamburg leading the sessions as head clinicians, joined by the talented and experienced Patricia Camarán and María Romero as assistants. Together, they will bring fresh ideas and expert guidance focused on the new artistic swimming rulebook, giving our swimmers a competitive edge heading into the season. Spots are limited, so make sure to register now and secure your place at this one-of-a-kind opportunity!</p><p>Stay connected with the Seattle Synchro community and follow us on Instagram at @SeattleSynchro for live updates, behind-the-scenes moments from the clinic, and all the latest news on competitions and events. We can''t wait to see you in the water!</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1781543078517-e1mpwspta5u.PNG"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1781543094934-3boxrmlswhq.PNG"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1781543358502-hbqfyjw3og6.JPG', 'announcement', 'Seattle Synchro', NULL, '["Synchro","eliteclinic","clinic2026","artisticswimming","swimming","seattle","washington","summerclinic"]', 'Seattle Synchro Elite Clinic 2026 | July Training Event', 'Seattle Synchro''s Elite Clinic 2026 is coming this July! Join us for four days of world-class artistic swimming training for 12U, Youth, and Junior swimmers.', 1, 1, '2026-06-15T17:09:35.445+00:00', '2026-06-15T17:05:17.362897+00:00', '2026-06-15T17:14:54.463398+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('85540780-8006-4052-9c6e-f282cc7068ab', 'Seattle Synchro Set to Shine at Junior Olympic Championships 2026', 'seattle-synchro-junior-olympics-2026', '', '<p>It''s the moment our swimmers have been training for all year! Seattle Synchro is heading to the Junior Olympic Championships, the final and biggest competition of the season. Our 12U, Youth, and Junior teams have put in countless hours of hard work, and now it''s time to show the world what they''re made of.</p><p>The competition runs from June 26th to July 4th in Ypsilanti, Michigan, bringing together some of the top artistic swimming talent from across the country. As the season finale, this is the ultimate stage for our athletes to showcase everything they''ve learned and perfected throughout the year. We are so proud of every swimmer representing Seattle Synchro, and we know they''re ready to bring their best energy, skill, and teamwork to the pool.</p><p>While our team competes, the fun doesn''t stop back home! Don''t forget that our Summer Camp and Elite Camp are happening throughout July and August, perfect opportunities for swimmers of all levels to keep improving and have a blast in the water.</p><p>Want to follow along with all the excitement? Make sure to follow @SeattleSynchro on Instagram for behind the scenes moments, competition updates, and everything happening with our artistic swimming Seattle community. Go Seattle Synchro!</p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1782149345086-cvjr829snu9.jpg', 'event', 'Patricia Camarán', NULL, '["synchro","competition","juniorolympics","2026","seattle","artisticswimming","synchronizedswimming"]', 'Seattle Synchro Heads to Junior Olympics 2026', 'Seattle Synchro is competing at the Junior Olympic Championships in Ypsilanti, Michigan. Follow along as our 12U, Youth, and Junior teams take the stage.', 1, 1, '2026-06-22T17:29:34.148+00:00', '2026-06-22T17:29:19.284611+00:00', '2026-06-22T17:34:02.18732+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('a469633f-4c91-4305-afe5-37b51568fe88', 'That''s a Wrap! Seattle Synchro Closes the Year at Junior Olympics 2026', 'thats-a-wrap-seattle-synchro-closes-the-year-at-junior-olympics-2026', 'What an incredible way to end the season! ', '<p>Seattle Synchro traveled to Ypsilanti, Michigan from June 27 to July 4 to compete at the Junior Olympics 2026, the final and most important synchronized swimming competition Seattle of the year. Our athletes brought everything they had to the pool, and the results speak for themselves.</p><p>Across all divisions, our team competed in 23 routines and an outstanding 18 of them made Finals. Our 12U teams showed tremendous heart and growth, while our Youth squad earned 2 Bronze medals and 1 Silver. But our Juniors and Senior athletes truly lit up the podium, taking home 2 Gold medals and 2 Silver medals in a performance that had the whole team cheering. Six teams, one goal, and a season to remember for our entire artistic swimming Seattle community.</p><p>To all our swimmers and families, thank you for an unforgettable 2025-2026 season! Enjoy your summer vacation, rest up, and get ready because the 2026-2027 season is just around the corner and we cannot wait to see what we accomplish together. Follow @SeattleSynchro on Instagram for updates, highlights, and everything coming up next for Seattle Synchro! </p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785954533063-88nxanroawh.jpeg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785954491570-xn4ym5n5wot.jpeg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785954482096-gw1isrf1hu8.jpeg"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785954690856-lctxys4te3a.jpg', 'competition', 'Patricia Camaran', NULL, '["JOs","competition","seattlesynchro","synchro","lastcompetition","seattle","sport","artisticswimming","synchronizedswimming"]', 'Seattle Synchro Wins Gold at Junior Olympics 2026', NULL, 1, 1, '2026-07-27T19:23:11.423+00:00', '2026-07-13T22:18:22.543045+00:00', '2026-08-05T18:31:36.05797+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('d6c07402-1b99-4aca-96b1-f81e55b39adc', 'Seattle Synchro Elite Summer Clinic 2026 Recap', 'seattle-synchro-elite-summer-clinic-2026-recap', '', '<p>Seattle Synchro just closed out an incredible week of training at Elite Summer Clinic 2026, and our athletes are coming back with new skills, sharper technique, and a whole lot of inspiration. This clinic brought together swimmers from across the region for a week focused on growth, connection, and world class coaching, exactly the kind of experience that makes artistic swimming Seattle families love being part of.</p><p>From July 27th to 30th, athletes gathered at Newport Hills Swim and Tennis Club, with swimmers traveling in from Colorado, Las Vegas, and Arizona, joining talented athletes from several Seattle area clubs. The clinic was led by an incredible coaching lineup, including Olympic medalists Tammy McGregor of Team USA and Paula Klamburg of Spain, alongside coaches Patricia Camaran and Maria Romero. Beyond pool time, athletes rounded out their training with dance classes and CrossFit sessions to build strength, flexibility, and artistry. On the final day, swimmers worked with a sports psychologist, focusing on the mental side of the sport and building the confidence and focus that carry over into every competition.</p><p>Weeks like this are what keep pushing our program forward and strengthening the synchronized swimming competition Seattle community continues to build. Want to catch more moments like this? Follow us on Instagram @SeattleSynchro for behind the scenes clips, upcoming competitions, and everything happening with Seattle Synchro all season long!</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785784625208-10k57ru983h.jpeg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785784668199-xal5umoovts.jpeg"><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785784681980-twfvas4fgnd.jpeg"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1785784911384-96g6wttpg16.jpeg', 'event', 'Patricia Camaran', NULL, '["synchro","camp","eliteclinic","clinic2026","rtisticswimming","synchronizedswimming"]', 'Seattle Synchro Elite Summer Clinic 2026 Recap', 'Seattle Synchro athletes trained with Olympic medalists Tammy McGregor and Paula Klamburg at Elite Summer Clinic 2026. Get the highlights now.', 1, 1, '2026-08-03T19:18:34.34+00:00', '2026-08-03T19:18:30.043055+00:00', '2026-08-03T19:22:35.575313+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('8632ddea-f338-432f-ae85-fcd6f4660fd9', 'Seattle Synchro Summer Camps 2026 Recap', 'seattle-synchro-summer-camps-2026-recap', '', '<p>What a summer it has been at Seattle Synchro! Our 2026 Summer Camps brought together two wonderful weeks of artistic swimming Seattle families won''t forget. Girls with big smiles and even bigger enthusiasm jumped into the pool ready to learn a brand new sport, and they left as confident, skilled little athletes.</p><p>The first camp ran July 27 through 31 at Newport Hills Swim and Tennis Club, followed by a second week from August 3 through 7 at Somerset Recreational Pool. Each week welcomed a fresh group of eager campers who dove into the fundamentals of synchronized swimming, from basic strokes to fun choreography basics. Every camp wrapped up with a special final presentation, giving our campers the chance to show off everything they learned in front of proud families and friends. A huge thank you goes out to our incredible athletes who volunteered their time to help guide the campers, and to our coaches for their outstanding energy and dedication throughout both weeks. This kind of teamwork is what makes the Seattle Synchro community so special.</p><p>Want to see the highlights? Follow @SeattleSynchro on Instagram to catch behind-the-scenes moments, upcoming competitions, and everything happening with our artistic swimming team. Whether you are a current family or just discovering synchronized swimming competition Seattle style, there is always something exciting coming up next!</p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1786458226662-0jmspoea17xj.jpeg"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1786458338475-10k813zoofd.jpg', 'event', 'Patricia Camaran', NULL, '["synchro","camps","summer","summercamps","2026","newporthills","newport","somerset","pool","artisticswimming","synchronizedswimming"]', 'Seattle Synchro Summer Camps 2026 Recap', 'Seattle Synchro wrapped up two amazing weeks of artistic swimming summer camps in Seattle. See how our campers learned new skills and shined bright.', 1, 1, '2026-08-11T14:26:41.149+00:00', '2026-08-11T14:25:57.127269+00:00', '2026-08-11T14:28:05.860289+00:00');
INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_url`, `category`, `author`, `user_id`, `tags`, `meta_title`, `meta_description`, `read_time_minutes`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('2c19dd56-24b0-427e-a7be-440f50ac0a8f', 'Seattle Synchro Wraps Summer Conditioning 2026', 'seattle-synchro-wraps-summer-conditioning-2026', 'Splashing Into a New Season: Summer Conditioning 2026 Wraps Up!', '<p>Seattle Synchro just closed out an amazing preseason! Our Intermediate, 12U, Youth, and Junior swimmers spent the first three weeks of August putting in the work at Triangle Pool, building strength, stamina, and skills ahead of the 2026-2027 season. This kind of dedication early in the year is exactly what sets our artistic swimming Seattle community apart, and it shows just how committed our athletes are to growing together as a team.</p><p>Swimmers across all levels showed up ready to push themselves, sharpen technique, and build the kind of teamwork that makes synchronized swimming competition Seattle events so exciting to watch. Three weeks of focused conditioning means our team is entering the new season stronger, sharper, and more connected than ever. Huge congrats to every swimmer who put in the effort this summer!</p><p>With preseason in the books, we cannot wait to see what this season brings for Seattle Synchro. Want to catch all the splashes, practices, and behind-the-scenes moments? Follow us on Instagram @SeattleSynchro to stay in the loop on upcoming competitions, showcases, and team news. Here''s to a season full of learning, growth, and unforgettable memories. Let''s dive in! </p><img src="https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1788209129572-8rjjem9flw6.jpg"><p></p>', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/news/1788209184515-kblj1ovrit9.jpg', 'event', 'Patricia Camaran', NULL, '["synchro","summer2026","preseason","seattlesynchro","artisticswimming","synchronizedswimming","washington","seattle"]', 'Seattle Synchro Wraps Summer Conditioning 2026', 'Seattle Synchro completed three weeks of summer conditioning at Triangle Pool, gearing up for an exciting 2026-2027 artistic swimming season. Follow along', 1, 1, '2026-08-31T20:47:19.177+00:00', '2026-08-31T20:46:31.846826+00:00', '2026-08-31T20:47:19.328029+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('396d909a-8edd-4476-a478-7a0813cf580f', 'Lacey Ethier', 'Intermediate Lead Coach', NULL, 'Lacey Ethier has been an athlete, owner, and still serves as a coach for Seattle Synchro. Lacey has been coaching since 2007. She Produces multiple national team athletes and two Olympic athletes. She swam for Seattle Synchro from 1998-2002 and competed both nationally and internationally as well as at the 2003 Olympic Trials. Lacey owned the club from 2011 to 2022 and has been the foundation of our success. Ethier has served as assistant coach to the 12& U National team in 2012. Lacey is also the current Pacific Northwest Association Administrative Chair. She lives in Redmond with her husband Vincent, children Vivienne and Archer.', '["Olympic Trials Experience","PNA Administrative Chair"]', '["Level 3 USA Artistic Swimming Coach","Level 3F USA Artistic Swimming Judge","USA Artistic Swimming Skill Assessor"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645422174-uxqfqf00hcm.webp', 1, 3, '2026-05-05T16:05:02.064534+00:00', '2026-05-29T21:55:38.028281+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('e56379aa-21aa-4786-81f8-7dfe53cbe1b7', 'Patricia Camaran (Paty)', 'Assistant Coach - Youth Team Lead', NULL, 'Patricia Camaran (Paty) is one of the club''s assistant coaches and serves as lead coach for the Youth Team. Paty is a professional kinesiologist with over 10 years of experience. Her journey in the water began with artistic swimming, where she represented Venezuela internationally (2014-2015). More recently, she coached the Chilean National Artistic Swimming Team (2023-2024), attending the World Aquatics Championships in Fukuoka and Doha, as well as the 2023 Pan American Games. In addition to being a swimming instructor, she specializes in working with neurodivergent children. Paty enjoys spending her free time working out and watching podcasts.', '["Neurodivergent Children","Kinesiology"]', '["Level 3 USA Artistic Swimming Coach","DTC 2 STC 2","Judge L 1F","Bachelor degree in Physical therapy"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645380022-gar7gzjqzh.webp', 1, 1, '2026-05-05T15:59:17.475553+00:00', '2026-05-29T21:55:38.042834+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('c6e0f909-57ec-4f55-9749-edeef418e741', 'Daniela Garmendia', 'Head Coach & Owner', 'info@seattlesynchro.com', 'Daniela is the Club''s Head Coach and owner. She coaches a variety of programs and leads the 13-15 Youth Squad. Originally from Venezuela, Daniela competed internationally as part of the Venezuelan national team. In 2016 had her last appearance representing her country at the Olympic Qualifiers in Rio 2016. She also swam collegiate synchro at Lindenwood University where her team took home the title in 2014 and in 2015 won Senior Nationals. In 2017, she graduated with a Bachelor Degree in Athletic training and moved to the Northwest. Daniela also served as the Assistant Coach for the Junior National Team 2019 and again in 2022 for Junior Worlds. In addition to coaching, Daniela is a personal trainer. She enjoys choreographing, dancing, and has a particular interest in the developing of emotional intelligence through sports. Her hobbies are snowboarding with her husband Camran, hiking, and dancing.', '["Artistic Impression","Emotional Intelligence","Music editor","Choreographer"]', '["Level 3 USA Artistic Swimming Coach","DTC 2 STC 2","Judge L 2F","USA Artistic Swimming Skill Assessor","Bachelor degree in Athletic Training","2025 West Zone coach of the year"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645357992-mslir4kn0s9.webp', 1, 0, '2026-05-03T04:30:52.142903+00:00', '2026-05-29T21:55:38.019355+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('21d97268-2571-4dc5-b9de-db1a438657c0', 'Ivy Huang', 'Assistant Youth & 12U Coach', NULL, 'Ivy is a former athlete of Seattle Synchro, swimming with the club for 10 years. She has competed and medaled in numerous competitions, including Junior Olympics, Junior Nationals, and US Opens. She recently moved back to the Seattle area after finishing her undergraduate degree in Neuroscience at Northwestern University. ', '["National competitor"]', '[]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645465774-4ap7cg8sn2j.webp', 1, 7, '2026-05-05T16:21:45.744498+00:00', '2026-05-29T21:55:38.009066+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('b3b027f8-e13d-4aac-8810-3b8fe86eed83', 'Carlie Vasquez', 'Swimming & Strengthening Coach', NULL, 'Carlie has been coaching for over 10 years. She has helped a number of athletes achieve great feats and get them at elite levels. She has a degree as an exercise specialist and uses that to create dryland workouts for teams and individuals. She currently coaches for Wave aquatics swimming and is the head coach for the High School team. She also works helping clients with aquatic therapeutic exercises and teaching kids on the spectrum how to swim. She has travelled to China while coaching a team of Washington State''s elite athletes at an international meet.', '["Swimming technique","Head Coach for the High School team"]', '[]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1777997871143-s8xlidf46y.webp', 1, 5, '2026-05-05T16:18:07.219131+00:00', '2026-05-29T21:55:38.028037+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('bfa54998-4b32-4c15-9374-8a8bc6d9a854', 'Maya Reistad', 'Athlete & Novice Lead Coach', NULL, 'Maya Reistad, a 16-year-old senior athlete who will graduate in 2026, has been with Seattle Synchro for 8 years, advancing from novice to the junior age group. She has competed in numerous Junior Olympic and National competitions. Maya began assisting with coaching in her 6th year and started leading summer camps at Pro Club at age 14. Last year, she served as the novice coach for Seattle Synchro and plans to continue. She was also awarded club athlete of the year in 2024.', '["Junior Age Group","National competitor","Gold medalist at Junior Olympic Championship"]', '["2024 Club Athlete of the Year"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645487353-4ejpmc05s5v.webp', 0, 8, '2026-05-05T16:23:47.269764+00:00', '2026-08-11T19:19:39.72937+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('f86f2c53-e320-4fae-a1d5-b7c733ac51c5', 'Claire Evans', 'Age Group Coach', NULL, 'Claire has been with the team since 2022, primarily helping out with the age group teams. Claire swam for the Pirouettes of Texas in Dallas for her entire age group career, and as a Pirouette was a South Zone champion in team, duet, and solo. Claire moved to Seattle from Nashville, TN, where she pursued a PhD in Political Science. Claire now works in Seattle at King County Metro Transit as a social science researcher.', '["PhD in Political Science"]', '["Level 3 USA Artistic Swimming Coach"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1777998007842-0xo83k4tc2h.webp', 1, 6, '2026-05-05T16:19:35.141225+00:00', '2026-05-29T21:55:38.010678+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('fddb1864-0a31-4e04-ba09-250cb7298c28', 'Jocilyn Sayler', 'Coach', NULL, 'Jocilyn has coached for Seattle since 2010 and assists our junior team. Jocilyn competed for the majority of her synchro career at Seattle where she swam at several national level meets and US Opens. She also swam for WAVE Aquatics and high school swim teams, where she competed at WIAA State Championships in medley and backstroke events. She has enjoyed working with athletes both at home and abroad develop their talents and qualify for national teams. Her athletes consistently place in finals at Junior Olympics, and she has produced multiple national team athletes and two Olympic athletes. Jocilyn has served as a coach for the US National Team, US National Team Program Manager and has a Master''s degree in Sports Industry Management from Georgetown University. Jocilyn also serves as the Officials Chair for the Pacific Northwest Association and Vice President of Member Development for USA Artistic Swimming as part of the Board of Directors.', '["US National Team Experience","USA Artistic Swimming Board of Directors"]', '["Level 3 USA Artistic Swimming Coach","Level 3 Judge","Master''s Degree in Sports Industry Management"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1779113324357-ahurvfx5aw9.webp', 1, 11, '2026-05-05T16:08:10.950447+00:00', '2026-05-29T21:55:38.029003+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('d7e0cefb-011e-4c23-b7a1-0f9574d03b3e', 'Sophie Lin', 'Athlete & Novice Lead Coach', NULL, 'Sophie''s synchro journey started 8 years ago, and she is a member of the junior team at Seattle Synchro. She has competed at numerous nation-wide competitions and been invited to All-Star Camp and Elite Camp. Her team won gold at the 2023 and 2024 Junior Olympics Championships. Sophie has co-led and helped coach summer camps, summer conditioning, and 12U solos and duet. When she''s not in the pool, Sophie enjoys baking, reading, solving puzzles, listening to music, making cards, and volunteering.', '["National competitor"]', '["Level 2 coach","Judge L2","DTC 1","Pacific Northwest Athlete Representative","2026 West Zone  Athlete of the Year","2023 & 2025 Athlete of the Year Seattle Synchronized Swim Team","2023 & 2024 Gold medalist at Junior Olympics Championship"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645542737-2tho1z9ldrt.webp', 1, 10, '2026-05-05T16:28:49.515044+00:00', '2026-08-24T18:58:13.797921+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('8672c39d-bbd1-4102-920e-1a04db57d128', 'Maria Romero (Coach Mafer)', 'Assistant Coach - Junior Team Lead', NULL, 'Maria is one of the club''s assistant coaches and serves as lead coach for the Junior Team. Maria Fernanda Romero Ochoa, a former member of the Venezuelan National artistic swimming team, has achieved excellence both as an athlete and a coach. She secured multiple medals in international competitions, including the Central American and South American championships. Served as head coach for the Elite Club for a year, focusing on enhancing athletes'' basic skills. In 2021, Maria earned her bachelor''s degree in physical therapy and worked with pediatric and geriatric patients for three years. Beyond her professional pursuits, she enjoys quality time with family, and loves CrossFit and dance. Maria''s journey is a fusion of dedication and passion for artistry and physical vitality.', '["Choreographer","Nutrition"]', '["Level 3 USA Artistic Swimming Coach","Bachelor''s Degree in Physical Therapy","DTC 2 STC 2","Judge L 1F"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645402228-zcrz9nbgha.webp', 1, 2, '2026-05-05T16:03:04.630044+00:00', '2026-05-29T21:55:38.060551+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('6c31a5ee-325a-41da-8e04-9cc7394cbfdc', 'Giordana Ventura', 'Intermediate & Novice Assistant Coach', NULL, 'Giordana, a senior athlete who will graduate in 2026, has been coaching for three seasons and is the assistant coach of intermediate and novice teams. She swam with Seattle Synchro for 6 years. During that time, she learned valuable lessons about perseverance, respect, coordination, power, and teamwork. Although she no longer participates as a swimmer, Giordana now coaches, which allows her to continue learning from the sport while also teaching others.', '[]', '[]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778645511102-kl054nffry.jpg', 0, 9, '2026-05-05T16:25:10.743499+00:00', '2026-08-11T19:19:01.074448+00:00');
INSERT INTO `coaches` (`id`, `name`, `title`, `email`, `bio`, `specialties`, `certifications`, `image_url`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES ('29fad30b-6b57-43f0-9e27-d277ff42df62', 'Yuki Maekawa', 'Age Group Coach', NULL, 'Yuki Maekawa is Seattle Synchro''s longest serving coach, having coached for the club since 1991. She will continue to assist a variety of teams throughout the year. She brings a vast wealth of knowledge to Seattle. Yuki was a member of the Japanese National team during the 1970s and in 2006 was awarded the United States Age Group Coach of the Year award. During her time at Seattle Synchro she has consistently placed swimmers in finals in both national, and international competition, producing multiple national team athletes and two Olympic athletes. Her daughters also swam for Seattle and went on to train at Stanford University, the University of Incarnate Word and Team USA. In addition to working with Seattle Synchro age groupers, Yuki also coaches a masters synchro program based on the eastside. She currently lives in Tukwila with her husband Zen and she enjoys traveling to Japan to visit her family.', '["Age Group Programs","Japanese National Team Member","33+ Years Experience","Figures"]', '["Level 3 USA Artistic Swimming Coach","2006 US Age Group Coach of the Year"]', 'https://hfyxcakixklryajpnszd.supabase.co/storage/v1/object/public/coaches/1778644513067-x3fanh9c4b.webp', 1, 4, '2026-05-05T16:16:35.924113+00:00', '2026-05-29T21:55:38.01865+00:00');
